                   <Pencil className="w-3 h-3" />
                 </button>
               )}
             </div>
           )}
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-3">
             <div className="text-right hidden sm:block">
               <p className="text-sm font-medium text-slate-900">{state.currentUser?.firstName} <span className="text-xs text-slate-400">@{state.currentUser?.username}</span></p>
               <p className="text-xs text-slate-500 capitalize">{state.currentRole === 'organizer' ? 'Organisateur' : 'Bénévole'}</p>
             </div>

             {/* Profile Trigger */}
             <button 
                onClick={state.currentRole === 'volunteer' ? openProfileModal : undefined}
                className={`relative ${state.currentRole === 'volunteer' ? 'cursor-pointer hover:ring-2 hover:ring-primary-300 rounded-full transition-all' : ''}`}
             >
                {state.currentUser?.avatar ? (
                    <img src={state.currentUser.avatar} alt="Profile" className="w-9 h-9 rounded-full object-cover border border-slate-200" />
                ) : (
                    <div className="w-9 h-9 rounded-full bg-primary-100 text-primary-700 flex items-center justify-center font-bold">
                      {state.currentUser?.firstName[0]}
