             <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100">
                <p className="text-slate-500 text-xs font-medium uppercase tracking-wider mb-1">Missions</p>
                <p className="text-3xl font-extrabold text-slate-900">{totalMissions}</p>
             </div>
             <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100">
