                className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex flex-col justify-center items-center cursor-pointer hover:bg-primary-50 hover:border-primary-200 transition-colors group"
             >
                <Plus className="w-8 h-8 text-primary-500 mb-1 group-hover:scale-110 transition-transform" />
                <p className="text-primary-700 font-bold text-sm">Créer Mission</p>
             </button>
          </section>

          {/* Organizer Calendar */}
          <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-lg font-bold flex items-center gap-2">
                <CalendarIcon className="w-5 h-5 text-primary-500" />
                Calendrier des Missions
              </h2>
              <div className="flex items-center gap-4">
                 <button onClick={() => changeMonth(-1)} className="p-1 hover:bg-slate-100 rounded-full transition-colors"><ChevronLeft className="w-5 h-5" /></button>
                 <span className="font-semibold capitalize min-w-[120px] text-center">
                   {calendarDate.toLocaleString('fr-FR', { month: 'long', year: 'numeric' })}
                 </span>
                 <button onClick={() => changeMonth(1)} className="p-1 hover:bg-slate-100 rounded-full transition-colors"><ChevronRight className="w-5 h-5" /></button>
              </div>
            </div>

            <div className="grid grid-cols-7 gap-2 mb-2">
              {['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'].map(d => (
                <div key={d} className="text-center text-sm font-bold text-slate-400 py-2">{d}</div>
              ))}
            </div>

            <div className="grid grid-cols-7 gap-2">
              {/* Empty slots for offset */}
              {Array.from({ length: offset }).map((_, i) => (
                <div key={`empty-${i}`} className="h-16 bg-slate-50/50 rounded-xl"></div>
              ))}

              {/* Days */}
              {Array.from({ length: daysInMonth }).map((_, i) => {
                const day = i + 1;
                const currentDayDate = new Date(year, month, day);
                const isToday = new Date().toDateString() === currentDayDate.toDateString();

                // Correction Calendrier: Vérifie si le jour est inclus dans la période de la mission
                const hasMission = state.missions.some(m => {
                    const mStart = new Date(m.dateStart);
                    mStart.setHours(0,0,0,0);
                    const mEnd = new Date(m.dateEnd);
                    mEnd.setHours(23,59,59,999); 

                    const checkTime = currentDayDate.getTime();
                    return checkTime >= mStart.getTime() && checkTime <= mEnd.getTime();
                });

                return (
                  <button 
                    key={day}
                    onClick={() => handleCalendarDayClick(day)}
                    className={`h-16 rounded-xl flex items-center justify-center text-sm font-medium transition-all duration-200 border 
                      ${hasMission 
                        ? 'bg-primary-500 text-white border-primary-600 hover:bg-primary-600 shadow-md' 
                        : 'bg-slate-50 border-transparent text-slate-600 hover:bg-white hover:border-slate-200 hover:shadow-sm'
                      }
                      ${isToday && !hasMission ? 'ring-2 ring-primary-500 ring-offset-2' : ''}
                      ${isToday && hasMission ? 'ring-2 ring-white ring-offset-2 ring-offset-primary-500' : ''}
                    `}
                  >
                    {day}
                  </button>
                );
              })}
            </div>
          </section>

          {/* Missions List Management */}
          <section>
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold">Vos Missions à venir</h2>
            </div>
            {state.missions.length === 0 ? (
