          </div>
        </Modal>

        {/* View Participants Modal (Shared Component logic, placed here for Organizer view) */}
        <Modal 
            isOpen={!!viewingParticipantsMissionId} 
            onClose={() => setViewingParticipantsMissionId(null)} 
