        <Header />

        {/* Mobile Tab Navigation */}
        <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 p-2 flex justify-around z-30 pb-safe">
           <button 
            onClick={() => setActiveTab('dashboard')} 
            className={`flex flex-col items-center p-2 rounded-xl w-full ${activeTab === 'dashboard' ? 'text-primary-600 bg-primary-50' : 'text-slate-400'}`}
           >
             <LayoutDashboard className="w-5 h-5" />
             <span className="text-[10px] mt-1 font-medium">Accueil</span>
