           <button 
            onClick={() => setActiveTab('calendar')} 
            className={`flex flex-col items-center p-2 rounded-xl w-full ${activeTab === 'calendar' ? 'text-primary-600 bg-primary-50' : 'text-slate-400'}`}
           >
