                   {calendarDate.toLocaleString('fr-FR', { month: 'long', year: 'numeric' })}
                 </span>
                 <button onClick={() => changeMonth(1)} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors"><ChevronRight className="w-5 h-5" /></button>
              </div>
            </div>

            <div className="grid grid-cols-7 gap-2 mb-2">
              {['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'].map(d => (
                <div key={d} className="text-center text-sm font-bold text-slate-400 py-2">{d}</div>
              ))}
            </div>

            <div className="grid grid-cols-7 gap-2">
              {/* Empty slots for offset */}
              {Array.from({ length: offset }).map((_, i) => (
                <div key={`empty-${i}`} className="h-16 bg-slate-50/50 dark:bg-slate-800/50 rounded-xl"></div>
              ))}

              {/* Days */}
              {Array.from({ length: daysInMonth }).map((_, i) => {
                const day = i + 1;
                const currentDayDate = new Date(year, month, day);
                const isToday = new Date().toDateString() === currentDayDate.toDateString();

                const hasMission = orgMissions.some(m => {
                    const mStart = new Date(m.dateStart);
                    mStart.setHours(0,0,0,0);
                    const mEnd = new Date(m.dateEnd);
                    mEnd.setHours(23,59,59,999); 
                    const checkTime = currentDayDate.getTime();
                    return checkTime >= mStart.getTime() && checkTime <= mEnd.getTime();
                });

                return (
                  <button 
                    key={day}
                    onClick={() => handleCalendarDayClick(day)}
                    className={`h-16 rounded-xl flex items-center justify-center text-sm font-medium transition-all duration-200 border 
                      ${hasMission 
                        ? 'bg-primary-500 text-white border-primary-600 hover:bg-primary-600 shadow-md' 
                        : 'bg-slate-50 dark:bg-slate-800 border-transparent text-slate-600 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-700 hover:border-slate-200 dark:hover:border-slate-600 hover:shadow-sm'
                      }
                      ${isToday && !hasMission ? 'ring-2 ring-primary-500 ring-offset-2 dark:ring-offset-slate-900' : ''}
                      ${isToday && hasMission ? 'ring-2 ring-white dark:ring-slate-900 ring-offset-2 ring-offset-primary-500' : ''}
                    `}
                  >
                    {day}
                  </button>
                );
              })}
            </div>
          </section>

          {/* Missions List Management */}
          <section>
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-slate-900 dark:text-white">Vos Missions à venir</h2>
            </div>
            {orgMissions.length === 0 ? (
              <div className="text-center py-12 bg-white dark:bg-slate-900 rounded-2xl border border-dashed border-slate-200 dark:border-slate-800">
                <p className="text-slate-400">Aucune mission planifiée.</p>
                <Button variant="ghost" className="mt-2" onClick={() => setIsMissionModalOpen(true)}>Créer votre première mission</Button>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {orgMissions.map(mission => (
                  <MissionCard 
                    key={mission.id} 
                    mission={mission} 
                    role="organizer" 
                    currentUser={state.currentUser}
                    allUsers={state.users}
                    onAction={handleMissionAction}
                    onChat={setActiveChatMissionId}
                    onViewParticipants={setViewingParticipantsMissionId}
                  />
                ))}
              </div>
            )}
          </section>
        </main>

        {/* --- MODALS ORGANIZER --- */}

        {/* Org Code Modal */}
        <Modal isOpen={isOrgCodeModalOpen} onClose={() => setIsOrgCodeModalOpen(false)} title="Code de l'organisation">
            <div className="flex flex-col items-center justify-center space-y-6 py-4">
                <div className="w-20 h-20 bg-primary-50 dark:bg-primary-900/20 rounded-full flex items-center justify-center">
                    <Key className="w-10 h-10 text-primary-500" />
                </div>
                <div className="text-center">
                    <p className="text-sm text-slate-500 dark:text-slate-400 mb-2">Partagez ce code avec vos bénévoles pour qu'ils puissent rejoindre votre espace :</p>
                    <div className="flex items-center justify-center gap-3 bg-slate-100 dark:bg-slate-800 px-6 py-3 rounded-xl border border-slate-200 dark:border-slate-700">
                        <span className="text-2xl font-mono font-bold tracking-widest text-slate-900 dark:text-white">{state.currentOrganization?.code}</span>
                    </div>
                </div>
                <Button onClick={() => setIsOrgCodeModalOpen(false)} fullWidth>Fermer</Button>
            </div>
        </Modal>

        {/* Logout Modal */}
        <Modal isOpen={isLogoutModalOpen} onClose={() => setIsLogoutModalOpen(false)} title="Confirmer la déconnexion">
            <div className="space-y-4">
                <p className="text-slate-600 dark:text-slate-300">Êtes-vous sûr de vouloir vous déconnecter de votre espace organisateur ?</p>
                <div className="flex gap-3">
                    <Button variant="secondary" fullWidth onClick={() => setIsLogoutModalOpen(false)}>Annuler</Button>
                    <Button variant="danger" fullWidth onClick={logout}>Déconnexion</Button>
                </div>
            </div>
        </Modal>

        {/* Create/Edit Mission Modal */}
        <Modal isOpen={isMissionModalOpen} onClose={() => setIsMissionModalOpen(false)} title={missionFormData.id ? "Modifier la mission" : "Créer une mission"}>
          <div className="space-y-4">
            <Input label="Titre" value={missionFormData.title} onChange={e => setMissionFormData({...missionFormData, title: e.target.value})} />
            <div className="grid grid-cols-2 gap-2">
               <Input label="Début" type="datetime-local" value={missionFormData.dateStart} onChange={e => setMissionFormData({...missionFormData, dateStart: e.target.value})} />
               <Input label="Fin (Optionnel)" type="datetime-local" value={missionFormData.dateEnd || ''} onChange={e => setMissionFormData({...missionFormData, dateEnd: e.target.value})} />
            </div>
            <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Catégorie</label>
                <select 
                  className="w-full rounded-xl border-slate-200 dark:border-slate-700 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm px-4 py-2 border bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
                  value={missionFormData.category}
                  onChange={e => setMissionFormData({...missionFormData, category: e.target.value as any})}
                >
                  <option value="Event">Event</option>
                  <option value="Maintenance">Maintenance</option>
                  <option value="Social">Social</option>
                  <option value="Autre">Autre</option>
                </select>
            </div>
            <Input label="Lieu" value={missionFormData.location} onChange={e => setMissionFormData({...missionFormData, location: e.target.value})} />
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Description</label>
              <textarea 
                className="w-full rounded-xl border-slate-200 dark:border-slate-700 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm px-4 py-2 border bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
                rows={3}
                value={missionFormData.description}
                onChange={e => setMissionFormData({...missionFormData, description: e.target.value})}
              />
            </div>
            {missionFormData.id && (
                <div className="pt-2 border-t border-slate-100 dark:border-slate-800">
                    <h4 className="font-bold text-slate-800 dark:text-slate-200 text-sm mb-2 flex items-center gap-2">
                        <Users className="w-4 h-4 text-primary-500" />
                        Participants inscrits
                    </h4>
                    <div className="bg-slate-50 dark:bg-slate-800 rounded-xl p-3 max-h-40 overflow-y-auto">
                         <ParticipantsList participantIds={state.missions.find(m => m.id === missionFormData.id)?.participants || []} />
                    </div>
                </div>
            )}
            <div className="flex flex-col gap-3 pt-2">
                <Button fullWidth onClick={handleSaveMission}>{missionFormData.id ? "Enregistrer les modifications" : "Publier la mission"}</Button>
                {missionFormData.id && (
                    <Button fullWidth variant="danger" type="button" onClick={(e) => handleDeleteMission(e)}>Supprimer la mission</Button>
                )}
            </div>
          </div>
        </Modal>

        {/* Update Org Name Modal */}
        <Modal isOpen={isOrgNameModalOpen} onClose={() => setIsOrgNameModalOpen(false)} title="Nom de l'organisation">
          <div className="space-y-4">
            <Input label="Nom de l'organisation" value={orgNameInput} onChange={e => setOrgNameInput(e.target.value)} />
            <Button fullWidth onClick={handleUpdateOrgName}>Sauvegarder</Button>
          </div>
        </Modal>

        <Modal isOpen={!!viewingParticipantsMissionId} onClose={() => setViewingParticipantsMissionId(null)} title={`Participants - ${viewingMission?.title || 'Mission'}`}>
            <div className="max-h-[60vh] overflow-y-auto">
                 <ParticipantsList participantIds={viewingMission?.participants || []} />
            </div>
        </Modal>

        {activeChatMissionId && (
          <ChatDrawer 
            mission={state.missions.find(m => m.id === activeChatMissionId)!}
            currentUser={state.currentUser!}
            onClose={() => setActiveChatMissionId(null)}
            onSendMessage={handleSendMessage}
          />
        )}
      </div>
    );
  }

  // 3. VOLUNTEER DASHBOARD
  if (state.currentRole === 'volunteer') {
    if (!state.currentOrganization && state.currentUser?.organizationIds && state.currentUser.organizationIds.length > 0) {
       // Should not happen due to initial logic but safe guard
       const firstOrg = state.organizations.find(o => o.id === state.currentUser!.organizationIds![0]);
       if(firstOrg) setState(prev => ({...prev, currentOrganization: firstOrg}));
    }

    const currentOrgId = state.currentOrganization?.id;

    // Filter missions by CURRENT Organization context
    const allOrgMissions = state.missions.filter(m => m.organizationId === currentOrgId);

    const myMissions = allOrgMissions.filter(m => m.participants.includes(state.currentUser!.id));
    const allAvailableMissions = allOrgMissions.filter(m => !m.participants.includes(state.currentUser!.id));

    const displayedMissions = selectedCategory === 'Tout' 
        ? allAvailableMissions 
        : allAvailableMissions.filter(m => m.category === selectedCategory);

    const viewingMission = viewingParticipantsMissionId 
        ? state.missions.find(m => m.id === viewingParticipantsMissionId)
        : null;

    return (
      <div className="min-h-screen bg-slate-50 dark:bg-slate-950 pb-20">
        <Header />

        {/* Mobile Tab Navigation */}
        <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 p-2 flex justify-around z-30 pb-safe">
           <button onClick={() => setActiveTab('dashboard')} className={`flex flex-col items-center p-2 rounded-xl w-full ${activeTab === 'dashboard' ? 'text-primary-600 dark:text-primary-400 bg-primary-50 dark:bg-primary-900/20' : 'text-slate-400'}`}>
             <LayoutDashboard className="w-5 h-5" />
             <span className="text-[10px] mt-1 font-medium">Accueil</span>
           </button>
           <button onClick={() => setActiveTab('calendar')} className={`flex flex-col items-center p-2 rounded-xl w-full ${activeTab === 'calendar' ? 'text-primary-600 dark:text-primary-400 bg-primary-50 dark:bg-primary-900/20' : 'text-slate-400'}`}>
             <Search className="w-5 h-5" />
             <span className="text-[10px] mt-1 font-medium">Explorer</span>
           </button>
        </div>

        <main className="max-w-3xl mx-auto px-4 py-6 space-y-8">

          {/* Welcome Section */}
          {activeTab === 'dashboard' && (
            <>
              {!state.currentOrganization ? (
                 <div className="bg-white dark:bg-slate-900 rounded-3xl p-8 text-center border border-slate-200 dark:border-slate-800 shadow-sm">
                    <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4">
                        <Building className="w-8 h-8 text-slate-400" />
                    </div>
                    <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-2">Bienvenue !</h2>
                    <p className="text-slate-500 dark:text-slate-400 mb-6">Vous n'avez rejoint aucune association pour le moment.</p>
                    <Button onClick={() => setIsManageOrgsModalOpen(true)}>Rejoindre une association</Button>
                 </div>
              ) : (
                <>
                  <div className="bg-gradient-to-r from-primary-600 to-emerald-500 dark:from-primary-700 dark:to-emerald-600 rounded-3xl p-6 text-white shadow-lg shadow-primary-200 dark:shadow-none">
                    <h2 className="text-2xl font-bold mb-2">Bonjour, {state.currentUser?.firstName} !</h2>
                    <p className="opacity-90 mb-6 text-sm">Prêt à changer les choses avec <strong>{state.currentOrganization.name}</strong> ?</p>
                    <div className="flex gap-3">
                      <div className="bg-white/20 backdrop-blur-sm rounded-xl px-4 py-2 flex-1">
                          <span className="block text-2xl font-bold">{myMissions.length}</span>
                          <span className="text-xs opacity-80">Missions</span>
                      </div>
                      <div className="bg-white/20 backdrop-blur-sm rounded-xl px-4 py-2 flex-1">
                          <span className="block text-2xl font-bold">12h</span>
                          <span className="text-xs opacity-80">Cumulées</span>
                      </div>
                    </div>
                  </div>

                  {/* My Planning */}
                  <div>
                    <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-4 flex items-center gap-2">
                      <CalendarIcon className="w-5 h-5 text-primary-500" /> 
                      Mon Planning
                    </h3>
                    {myMissions.length > 0 ? (
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {myMissions.map(mission => (
                          <MissionCard 
                            key={mission.id} 
                            mission={mission} 
                            role="volunteer" 
                            currentUser={state.currentUser}
                            allUsers={state.users}
                            onAction={handleMissionAction}
                            onChat={setActiveChatMissionId}
                            onViewParticipants={setViewingParticipantsMissionId}
                          />
                        ))}
                      </div>
                    ) : (
                      <div className="text-center py-10 bg-white dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-slate-800 border-dashed">
                        <p className="text-slate-400">Aucune mission prévue.</p>
                        <Button variant="ghost" size="sm" onClick={scrollToMissions} className="mt-2 text-primary-600 dark:text-primary-400">
                          Trouver une mission
                        </Button>
                      </div>
                    )}
                  </div>
                </>
              )}
            </>
          )}

          {/* Explore / Calendar */}
          {(activeTab === 'calendar' || activeTab === 'dashboard') && state.currentOrganization && (
            <div className={activeTab === 'dashboard' ? 'hidden md:block' : ''}>
               <h3 id="available-missions" className="text-lg font-bold text-slate-900 dark:text-white mb-4 flex items-center gap-2">
                  <Search className="w-5 h-5 text-primary-500" />
                  Missions Disponibles
               </h3>
               <div className="flex gap-2 overflow-x-auto pb-4 scrollbar-hide">
                 {['Tout', 'Social', 'Maintenance', 'Event', 'Autre'].map((cat) => (
                   <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-4 py-1.5 rounded-full text-sm font-medium whitespace-nowrap transition-colors ${selectedCategory === cat ? 'bg-slate-900 dark:bg-white text-white dark:text-slate-900 shadow-md' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700'}`}>{cat}</button>
                 ))}
               </div>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {displayedMissions.map(mission => (
                    <MissionCard 
                      key={mission.id} 
                      mission={mission} 
                      role="volunteer" 
                      currentUser={state.currentUser}
                      allUsers={state.users}
                      onAction={handleMissionAction}
                      onChat={setActiveChatMissionId}
                      onViewParticipants={setViewingParticipantsMissionId}
                    />
                 ))}
                 {displayedMissions.length === 0 && (
                   <p className="col-span-full text-center text-slate-500 dark:text-slate-400 py-10">
                     {selectedCategory === 'Tout' 
                        ? "Toutes les missions sont prises pour le moment !" 
                        : `Aucune mission disponible dans la catégorie "${selectedCategory}".`}
                   </p>
                 )}
               </div>
            </div>
          )}
        </main>

        {/* --- MODALS VOLUNTEER --- */}

        {/* Manage Organizations Modal */}
        <Modal isOpen={isManageOrgsModalOpen} onClose={() => setIsManageOrgsModalOpen(false)} title="Mes Associations">
            <div className="space-y-6">
                {/* Join New */}
                <div className="bg-slate-50 dark:bg-slate-800/50 p-4 rounded-xl border border-slate-200 dark:border-slate-700">
                    <h4 className="text-sm font-bold text-slate-900 dark:text-white mb-2">Rejoindre une association</h4>
                    <div className="flex gap-2">
                        <Input 
                            placeholder="Entrez le code ici..." 
                            value={joinCodeInput} 
                            onChange={e => setJoinCodeInput(e.target.value)}
                        />
                        <Button onClick={handleJoinOrganization} disabled={!joinCodeInput.trim()}>
                            <Plus className="w-5 h-5" />
                        </Button>
                    </div>
                </div>

                {/* List of Orgs */}
                <div>
                    <h4 className="text-sm font-bold text-slate-900 dark:text-white mb-2">Mes associations</h4>
                    <div className="space-y-2">
                        {state.currentUser?.organizationIds?.map(orgId => {
                            const org = state.organizations.find(o => o.id === orgId);
                            if (!org) return null;
                            const isActive = state.currentOrganization?.id === orgId;

                            return (
                                <div key={org.id} className={`flex items-center justify-between p-3 rounded-xl border ${isActive ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/10' : 'border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900'}`}>
                                    <div className="flex items-center gap-3">
                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center ${isActive ? 'bg-primary-100 text-primary-600' : 'bg-slate-100 text-slate-500'}`}>
                                            <Building className="w-4 h-4" />
                                        </div>
                                        <div>
                                            <p className={`font-medium text-sm ${isActive ? 'text-primary-700 dark:text-primary-400' : 'text-slate-900 dark:text-white'}`}>{org.name}</p>
                                            {isActive && <span className="text-[10px] text-primary-600 flex items-center gap-1"><CheckCircle className="w-3 h-3"/> Active</span>}
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-1">
                                        {!isActive && (
                                            <Button size="sm" variant="secondary" onClick={() => handleSwitchOrganization(org.id)}>Voir</Button>
                                        )}
                                        <button 
                                            onClick={() => handleLeaveOrganization(org.id)}
                                            className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                                            title="Quitter l'association"
                                        >
                                            <LogOut className="w-4 h-4" />
                                        </button>
                                    </div>
                                </div>
                            );
                        })}
                        {(!state.currentUser?.organizationIds || state.currentUser.organizationIds.length === 0) && (
                            <p className="text-center text-sm text-slate-500 italic py-4">Vous n'avez rejoint aucune association.</p>
                        )}
                    </div>
                </div>
            </div>
        </Modal>

        {/* Logout Modal */}
        <Modal isOpen={isLogoutModalOpen} onClose={() => setIsLogoutModalOpen(false)} title="Confirmer la déconnexion">
            <div className="space-y-4">
                <p className="text-slate-600 dark:text-slate-300">Êtes-vous sûr de vouloir vous déconnecter ?</p>
                <div className="flex gap-3">
                    <Button variant="secondary" fullWidth onClick={() => setIsLogoutModalOpen(false)}>Annuler</Button>
                    <Button variant="danger" fullWidth onClick={logout}>Déconnexion</Button>
                </div>
            </div>
        </Modal>

        {/* Edit Profile Modal */}
        <Modal isOpen={isProfileModalOpen} onClose={() => setIsProfileModalOpen(false)} title="Mon Profil">
           <div className="space-y-4">
              <div className="flex justify-center mb-4">
                 <img src={profileFormData.avatar || 'https://via.placeholder.com/100'} className="w-20 h-20 rounded-full border-2 border-slate-200 dark:border-slate-700 object-cover" />
              </div>
              <Input label="Avatar URL (ex: https://...)" value={profileFormData.avatar || ''} onChange={e => setProfileFormData({...profileFormData, avatar: e.target.value})} />
              <div className="grid grid-cols-2 gap-2">
                <Input label="Prénom" value={profileFormData.firstName || ''} onChange={e => setProfileFormData({...profileFormData, firstName: e.target.value})} />
                <Input label="Nom" value={profileFormData.lastName || ''} onChange={e => setProfileFormData({...profileFormData, lastName: e.target.value})} />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Centres d'intérêt (Min. 3)</label>
                <div className="flex gap-2 mb-2">
                  <Input value={interestInput} onChange={e => setInterestInput(e.target.value)} placeholder="Ajouter (ex: Jardinage)" onKeyDown={e => e.key === 'Enter' && handleAddInterest()} className="flex-1" />
                  <Button type="button" onClick={handleAddInterest} size="sm" variant="secondary"><Plus className="w-4 h-4" /></Button>
                </div>
                <div className="flex flex-wrap gap-2 mt-2">
                  {profileFormData.interests?.map((interest, idx) => (
                    <span key={idx} className="bg-primary-50 dark:bg-primary-900/30 text-primary-700 dark:text-primary-300 px-3 py-1 rounded-full text-xs font-medium flex items-center">
                       {interest}
                       <button onClick={() => handleRemoveInterest(interest)} className="ml-1 hover:text-red-500"><X className="w-3 h-3" /></button>
                    </span>
                  ))}
                </div>
                {profileFormData.interests && profileFormData.interests.length < 3 && <p className="text-xs text-red-500 mt-1">Il manque encore {3 - profileFormData.interests.length} centre(s) d'intérêt.</p>}
              </div>
              <Button fullWidth onClick={handleSaveProfile} disabled={profileFormData.interests && profileFormData.interests.length < 3}>Sauvegarder</Button>
           </div>
        </Modal>

        <Modal isOpen={!!viewingParticipantsMissionId} onClose={() => setViewingParticipantsMissionId(null)} title={`Participants - ${viewingMission?.title || 'Mission'}`}>
            <div className="max-h-[60vh] overflow-y-auto">
                 <ParticipantsList participantIds={viewingMission?.participants || []} />
            </div>
        </Modal>

        {activeChatMissionId && (
          <ChatDrawer 
            mission={state.missions.find(m => m.id === activeChatMissionId)!}
            currentUser={state.currentUser!}
            onClose={() => setActiveChatMissionId(null)}
            onSendMessage={handleSendMessage}
          />
        )}
      </div>
    );
  }

  return null;
}

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  fullWidth?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  fullWidth = false, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center rounded-xl font-semibold transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-primary-600 text-white hover:bg-primary-700 focus:ring-primary-500 shadow-sm border border-transparent",
    secondary: "bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 focus:ring-slate-200 shadow-sm",
    danger: "bg-red-500 text-white hover:bg-red-600 focus:ring-red-500 shadow-sm border border-transparent",
    ghost: "bg-transparent text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-white",
  };

  const sizes = {
    sm: "px-4 py-2 text-xs min-h-[40px]",
    md: "px-6 py-3 text-sm md:text-base min-h-[48px]", // Standards mobiles
    lg: "px-8 py-4 text-base md:text-lg min-h-[56px]",
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${fullWidth ? 'w-full' : ''} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

import React from 'react';

interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: string;
  error?: string;
}

export const Input: React.FC<InputProps> = ({ label, error, className = '', ...props }) => {
  return (
    <div className="w-full">
      {label && (
        <label className="block text-sm font-semibold text-slate-700 dark:text-slate-200 mb-1.5 ml-1">
          {label}
        </label>
      )}
      <input
        className={`w-full min-h-[48px] rounded-xl border-slate-200 dark:border-slate-700 shadow-sm focus:border-primary-500 focus:ring-primary-500 text-base px-4 py-3 border transition-all bg-white dark:bg-slate-800 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 outline-none ${error ? 'border-red-300 focus:border-red-500 focus:ring-red-500' : ''} ${className}`}
        {...props}
      />
      {error && <p className="mt-1.5 text-xs text-red-500 font-medium ml-1">{error}</p>}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { 
  Users, Calendar as CalendarIcon, LogOut, Plus, 
  BarChart3, LayoutDashboard, Heart, Search, Settings, Pencil, X,
  ChevronLeft, ChevronRight, Building, Tag, Eye, Key, Copy, CheckCircle,
  ArrowLeft
} from 'lucide-react';
import { BarChart, Bar, XAxis, Tooltip as RechartsTooltip, ResponsiveContainer, Cell } from 'recharts';

import { MissionCard } from './components/MissionCard';
import { ChatDrawer } from './components/ChatDrawer';
import { Button } from './components/ui/Button';
import { Input } from './components/ui/Input';
import { Modal } from './components/ui/Modal';
import { MOCK_MISSIONS, MOCK_USERS, MOCK_ORG, MOCK_ORG_2 } from './constants';
import { AppState, Mission, Role, User, Organization } from './types';

// --- MAIN APP COMPONENT ---

export default function App() {
  const [state, setState] = useState<AppState>({
    currentUser: null,
    currentRole: 'none',
    currentOrganization: null,
    managedOrganization: MOCK_ORG,
    missions: MOCK_MISSIONS,
    users: MOCK_USERS,
    organizations: [MOCK_ORG, MOCK_ORG_2]
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'calendar' | 'volunteers'>('dashboard');
  const [activeChatMissionId, setActiveChatMissionId] = useState<string | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<string>('Tout');

  const [showOrgLogin, setShowOrgLogin] = useState(false);
  const [showVolunteerLogin, setShowVolunteerLogin] = useState(false);

  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [isMissionModalOpen, setIsMissionModalOpen] = useState(false);
  const [isOrgNameModalOpen, setIsOrgNameModalOpen] = useState(false);
  const [isCreateOrgModalOpen, setIsCreateOrgModalOpen] = useState(false);
  const [isCreateVolunteerModalOpen, setIsCreateVolunteerModalOpen] = useState(false);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

  const [isOrgCodeModalOpen, setIsOrgCodeModalOpen] = useState(false);
  const [isManageOrgsModalOpen, setIsManageOrgsModalOpen] = useState(false);
  const [joinCodeInput, setJoinCodeInput] = useState('');

  const [viewingParticipantsMissionId, setViewingParticipantsMissionId] = useState<string | null>(null);

  const [calendarDate, setCalendarDate] = useState(new Date());

  const [orgLoginData, setOrgLoginData] = useState({ email: '', password: '' });
  const [volunteerLoginData, setVolunteerLoginData] = useState({ username: '', password: '' });
  const [createVolunteerData, setCreateVolunteerData] = useState({ firstName: '', lastName: '', username: '', password: '' });

  const [rememberOrg, setRememberOrg] = useState(false);
  const [profileFormData, setProfileFormData] = useState<Partial<User>>({});
  const [interestInput, setInterestInput] = useState('');

  const [missionFormData, setMissionFormData] = useState<Partial<Mission>>({
    id: undefined,
    title: '', location: '', description: '', category: 'Event', dateStart: '', dateEnd: ''
  });
  const [orgNameInput, setOrgNameInput] = useState('');
  const [createOrgName, setCreateOrgName] = useState('');


  useEffect(() => {
    const savedSession = localStorage.getItem('bnevo_org_session');
    if (savedSession) {
      try {
        const session = JSON.parse(savedSession);
        if (session.role === 'organizer') {
          setState(prev => ({
            ...prev,
            currentUser: MOCK_USERS.find(u => u.role === 'organizer') || null,
            currentRole: 'organizer',
            currentOrganization: session.organization || prev.managedOrganization,
            managedOrganization: session.organization || prev.managedOrganization
          }));
        }
      } catch (e) {
        console.error("Failed to parse session", e);
        localStorage.removeItem('bnevo_org_session');
      }
    }
  }, []);

  const toLocalISOString = (date: Date) => {
    const pad = (num: number) => num.toString().padStart(2, '0');
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
  };

  const scrollToMissions = () => {
    const element = document.getElementById('available-missions');
    if (element) element.scrollIntoView({ behavior: 'smooth' });
  };

  const getDaysInMonth = (date: Date) => {
    const year = date.getFullYear();
    const month = date.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const firstDayObj = new Date(year, month, 1);
    let firstDay = firstDayObj.getDay();
    const offset = firstDay === 0 ? 6 : firstDay - 1;
    return { daysInMonth, offset, year, month };
  };

  const changeMonth = (delta: number) => {
    const newDate = new Date(calendarDate);
    newDate.setMonth(newDate.getMonth() + delta);
    setCalendarDate(newDate);
  };

  const handleCalendarDayClick = (day: number) => {
    const year = calendarDate.getFullYear();
    const month = calendarDate.getMonth();
    const startDate = new Date(year, month, day, 9, 0);
    const endDate = new Date(year, month, day, 12, 0);

    setMissionFormData({
      id: undefined, 
      title: '', 
      location: '', 
      description: '', 
      category: 'Event',
      dateStart: toLocalISOString(startDate),
      dateEnd: toLocalISOString(endDate)
    });
    setIsMissionModalOpen(true);
  };

  const handleOrgLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (orgLoginData.email && orgLoginData.password) {
      const orgUser = MOCK_USERS.find(u => u.role === 'organizer');
      const orgData = state.managedOrganization;
      setState(prev => ({
        ...prev,
        currentUser: orgUser || null,
        currentRole: 'organizer',
        currentOrganization: orgData
      }));
      setShowOrgLogin(false);
      if (rememberOrg) {
        localStorage.setItem('bnevo_org_session', JSON.stringify({ role: 'organizer', organization: orgData }));
      }
    }
  };

  const handleCreateOrganization = () => {
    if (!createOrgName.trim()) return;
    const newOrg: Organization = {
      id: `org-${Date.now()}`,
      name: createOrgName,
      code: `NEW-${new Date().getFullYear()}`
    };
    const newAdmin: User = {
      id: `admin-${Date.now()}`,
      firstName: 'Admin',
      lastName: createOrgName,
      username: 'admin_new',
      avatar: '',
      role: 'organizer',
      organizationIds: [newOrg.id]
    };
    setState(prev => ({
      ...prev,
      currentUser: newAdmin,
      currentRole: 'organizer',
      currentOrganization: newOrg,
      managedOrganization: newOrg,
      missions: [], 
      users: [...prev.users, newAdmin],
      organizations: [...prev.organizations, newOrg]
    }));
    localStorage.setItem('bnevo_org_session', JSON.stringify({ role: 'organizer', organization: newOrg }));
    setIsCreateOrgModalOpen(false);
    setShowOrgLogin(false);
  };

  const handleVolunteerLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const user = state.users.find(u => 
      u.role === 'volunteer' && 
      u.username.toLowerCase() === volunteerLoginData.username.toLowerCase() &&
      u.password === volunteerLoginData.password
    );
    if (user) {
      let initialOrg: Organization | null = null;
      if (user.organizationIds && user.organizationIds.length > 0) {
        initialOrg = state.organizations.find(o => o.id === user.organizationIds![0]) || null;
      }
      setState(prev => ({ ...prev, currentUser: user, currentRole: 'volunteer', currentOrganization: initialOrg }));
      setShowVolunteerLogin(false);
      setVolunteerLoginData({ username: '', password: '' });
    } else {
      alert("Pseudo ou mot de passe incorrect.");
    }
  };

  const handleCreateVolunteer = () => {
    if (!createVolunteerData.firstName || !createVolunteerData.username || !createVolunteerData.password) return;
    if (state.users.some(u => u.username.toLowerCase() === createVolunteerData.username.toLowerCase())) {
        alert("Ce pseudo est déjà pris.");
        return;
    }
    const newUser: User = {
        id: `u-${Date.now()}`,
        firstName: createVolunteerData.firstName,
        lastName: createVolunteerData.lastName || '',
        username: createVolunteerData.username,
        password: createVolunteerData.password,
        avatar: `https://ui-avatars.com/api/?name=${createVolunteerData.firstName}+${createVolunteerData.lastName || ''}&background=random`, 
        role: 'volunteer',
        interests: [],
        organizationIds: []
    };
    setState(prev => ({ ...prev, users: [...prev.users, newUser], currentUser: newUser, currentRole: 'volunteer', currentOrganization: null }));
    setIsCreateVolunteerModalOpen(false);
    setShowVolunteerLogin(false);
    setIsManageOrgsModalOpen(true);
  };

  const logout = () => {
    setState(prev => ({ ...prev, currentUser: null, currentRole: 'none' }));
    setActiveTab('dashboard');
    setIsLogoutModalOpen(false);
    localStorage.removeItem('bnevo_org_session');
  };

  const handleJoinOrganization = () => {
    if (!joinCodeInput.trim()) return;
    const orgToJoin = state.organizations.find(o => o.code === joinCodeInput.trim());
    if (!orgToJoin) {
      alert("Code organisation invalide.");
      return;
    }
    const updatedUser = {
      ...state.currentUser!,
      organizationIds: [...(state.currentUser?.organizationIds || []), orgToJoin.id]
    };
    setState(prev => ({
      ...prev,
      currentUser: updatedUser,
      currentOrganization: orgToJoin,
      users: prev.users.map(u => u.id === updatedUser.id ? updatedUser : u)
    }));
    setJoinCodeInput('');
  };

  const handleSwitchOrganization = (orgId: string) => {
    const org = state.organizations.find(o => o.id === orgId);
    if (org) setState(prev => ({ ...prev, currentOrganization: org }));
  };

  const handleLeaveOrganization = (orgId: string) => {
    if (!window.confirm("Quitter cette association ?")) return;
    const currentUserId = state.currentUser!.id;
    const updatedMissions = state.missions.map(m => {
      if (m.organizationId === orgId && m.participants.includes(currentUserId)) {
        return { ...m, participants: m.participants.filter(pid => pid !== currentUserId) };
      }
      return m;
    });
    const updatedUser = {
      ...state.currentUser!,
      organizationIds: state.currentUser!.organizationIds?.filter(id => id !== orgId) || []
    };
    const remainingOrgIds = updatedUser.organizationIds;
    let nextOrg = null;
    if (remainingOrgIds.length > 0) nextOrg = state.organizations.find(o => o.id === remainingOrgIds[0]) || null;
    setState(prev => ({
      ...prev,
      missions: updatedMissions,
      users: prev.users.map(u => u.id === currentUserId ? updatedUser : u),
      currentUser: updatedUser,
      currentOrganization: state.currentOrganization?.id === orgId ? nextOrg : prev.currentOrganization
    }));
  };

  const handleSaveProfile = () => {
    if (profileFormData.interests && profileFormData.interests.length < 3) {
      alert("Ajoutez au moins 3 intérêts.");
      return;
    }
    setState(prev => ({
      ...prev,
      currentUser: { ...prev.currentUser!, ...profileFormData } as User,
      users: prev.users.map(u => u.id === prev.currentUser!.id ? { ...u, ...profileFormData } as User : u)
    }));
    setIsProfileModalOpen(false);
  };

  const handleUpdateOrgName = () => {
    if (orgNameInput.trim()) {
      const updatedOrg = { ...state.currentOrganization!, name: orgNameInput };
      setState(prev => ({
        ...prev,
        currentOrganization: updatedOrg,
        managedOrganization: updatedOrg,
        organizations: prev.organizations.map(o => o.id === updatedOrg.id ? updatedOrg : o)
      }));
      setIsOrgNameModalOpen(false);
    }
  };

  const handleDeleteMission = (e: React.MouseEvent) => {
    e.preventDefault();
    if (!missionFormData.id) return;
    if (window.confirm("Supprimer cette mission ?")) {
        setState(prev => ({ ...prev, missions: prev.missions.filter(m => m.id !== missionFormData.id) }));
        setIsMissionModalOpen(false);
    }
  };

  const handleSaveMission = () => {
    if (!missionFormData.title || !missionFormData.dateStart || !state.currentOrganization) return;
    const finalDateEnd = missionFormData.dateEnd || missionFormData.dateStart;
    if (missionFormData.id) {
        setState(prev => ({
            ...prev,
            missions: prev.missions.map(m => m.id === missionFormData.id ? { ...m, ...missionFormData, dateEnd: finalDateEnd } as Mission : m)
        }));
    } else {
        const newMission: Mission = {
            id: `new-${Date.now()}`,
            organizationId: state.currentOrganization.id,
            title: missionFormData.title!,
            location: missionFormData.location || 'À définir',
            dateStart: missionFormData.dateStart!,
            dateEnd: finalDateEnd,
            description: missionFormData.description || '',
            category: (missionFormData.category as any) || 'Event',
            participants: [],
            chatMessages: []
        };
        setState(prev => ({ ...prev, missions: [...prev.missions, newMission] }));
    }
    setIsMissionModalOpen(false);
  };

  const handleMissionAction = (missionId: string) => {
    if (state.currentRole === 'volunteer') {
      setState(prev => {
        const mission = prev.missions.find(m => m.id === missionId);
        if (!mission || !prev.currentUser) return prev;
        const isRegistered = mission.participants.includes(prev.currentUser.id);
        const newParticipants = isRegistered 
            ? mission.participants.filter(id => id !== prev.currentUser!.id)
            : [...mission.participants, prev.currentUser.id];
        return { ...prev, missions: prev.missions.map(m => m.id === missionId ? { ...m, participants: newParticipants } : m) };
      });
    } else {
      const missionToEdit = state.missions.find(m => m.id === missionId);
      if (missionToEdit) {
          setMissionFormData({ ...missionToEdit });
          setIsMissionModalOpen(true);
      }
    }
  };

  const handleSendMessage = (missionId: string, text: string) => {
    if (!state.currentUser) return;
    const newMessage = {
      id: Date.now().toString(),
      userId: state.currentUser.id,
      userName: state.currentUser.firstName,
      userAvatar: state.currentUser.avatar,
      text,
      timestamp: Date.now()
    };
    setState(prev => ({ ...prev, missions: prev.missions.map(m => m.id === missionId ? { ...m, chatMessages: [...m.chatMessages, newMessage] } : m) }));
  };

  // --- UI COMPONENTS ---

  const Header = () => (
    <header className="sticky top-0 z-40 bg-white/90 dark:bg-slate-900/90 backdrop-blur-lg border-b border-slate-200 dark:border-slate-800">
      <div className="max-w-5xl mx-auto px-4 h-16 md:h-20 flex items-center justify-between">
        <div className="flex items-center gap-3">
           <div className="w-9 h-9 md:w-10 md:h-10 bg-primary-600 rounded-xl flex items-center justify-center shadow-lg shadow-primary-200 dark:shadow-none">
             <Heart className="w-5 h-5 text-white fill-current" />
           </div>
           <div className="flex flex-col">
             <span className="font-bold text-base md:text-xl tracking-tight text-slate-900 dark:text-white leading-none">BNEVO</span>
             {state.currentOrganization && (
               <div className="flex items-center gap-1 mt-1 text-[10px] md:text-xs text-slate-500 dark:text-slate-400 font-medium">
                 <span className="truncate max-w-[100px] md:max-w-[200px]">{state.currentOrganization.name}</span>
                 {state.currentRole === 'organizer' && (
                   <button onClick={() => { setOrgNameInput(state.currentOrganization!.name); setIsOrgNameModalOpen(true); }} className="hover:text-primary-600"><Pencil className="w-2.5 h-2.5" /></button>
                 )}
               </div>
             )}
           </div>
        </div>

        <div className="flex items-center gap-2 md:gap-4">
          <div className="flex items-center gap-2 md:gap-3">
             <div className="text-right hidden sm:block">
               {state.currentRole !== 'organizer' && (
                  <p className="text-sm font-bold text-slate-900 dark:text-white leading-none">{state.currentUser?.firstName}</p>
               )}
               <div className="flex items-center justify-end gap-1 mt-1">
                 <p className="text-[10px] text-slate-500 dark:text-slate-400 uppercase tracking-wider font-semibold">
                    {state.currentRole === 'organizer' ? 'Organisateur' : 'Bénévole'}
                 </p>
               </div>
             </div>

             <div className="flex items-center gap-1.5 md:gap-2">
                {state.currentRole === 'organizer' && (
                   <button onClick={() => setIsOrgCodeModalOpen(true)} className="p-2 md:p-2.5 text-primary-600 dark:text-primary-400 bg-primary-50 dark:bg-primary-900/20 rounded-xl hover:scale-105 transition-transform"><Key className="w-4 h-4 md:w-5 md:h-5" /></button>
                )}
                {state.currentRole === 'volunteer' && (
                   <button onClick={() => setIsManageOrgsModalOpen(true)} className="p-2 md:p-2.5 text-primary-600 dark:text-primary-400 bg-primary-50 dark:bg-primary-900/20 rounded-xl hover:scale-105 transition-transform"><Building className="w-4 h-4 md:w-5 md:h-5" /></button>
                )}
                <button onClick={state.currentRole === 'volunteer' ? () => { setProfileFormData({ ...state.currentUser }); setIsProfileModalOpen(true); } : undefined} className="relative active:scale-95 transition-transform">
                    <img src={state.currentUser?.avatar || `https://ui-avatars.com/api/?name=${state.currentUser?.firstName}&background=random`} alt="Profile" className="w-9 h-9 md:w-11 md:h-11 rounded-xl object-cover border-2 border-white dark:border-slate-800 shadow-sm" />
                </button>
             </div>
          </div>
          <button onClick={() => setIsLogoutModalOpen(true)} className="p-2 md:p-2.5 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-950/30 rounded-xl transition-all"><LogOut className="w-5 h-5" /></button>
        </div>
      </div>
    </header>
  );

  if (state.currentRole === 'none') {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50 dark:bg-slate-950">
        <div className="max-w-md w-full text-center space-y-8">
          <div className="mx-auto w-24 h-24 md:w-28 md:h-28 bg-primary-600 rounded-[2rem] flex items-center justify-center shadow-2xl shadow-primary-200 dark:shadow-none animate-bounce-slow">
            <Heart className="w-12 h-12 md:w-14 md:h-14 text-white fill-current" />
          </div>
          <div className="px-4">
            <h1 className="text-4xl md:text-5xl font-black text-slate-900 dark:text-white tracking-tight">BNEVO</h1>
            <p className="mt-4 text-base md:text-lg text-slate-600 dark:text-slate-400 leading-relaxed font-medium">
              Simplifiez la gestion de vos bénévoles. <br className="hidden md:block"/> Libérez votre temps associatif.
            </p>
          </div>

          <div className="grid grid-cols-1 gap-4 pt-8 px-4">
            {!showOrgLogin && !showVolunteerLogin ? (
              <>
                <button onClick={() => setShowOrgLogin(true)} className="group relative flex items-center p-5 md:p-6 bg-white dark:bg-slate-900 border-2 border-slate-100 dark:border-slate-800 rounded-2xl hover:border-primary-500 hover:shadow-xl transition-all active:scale-95">
                  <div className="text-left flex-1">
                    <h3 className="font-bold text-lg text-slate-900 dark:text-white group-hover:text-primary-600">Espace Organisation</h3>
                    <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Plannings, missions et équipes</p>
                  </div>
                  <LayoutDashboard className="w-7 h-7 text-slate-300 group-hover:text-primary-500" />
                </button>
                <button onClick={() => setShowVolunteerLogin(true)} className="group relative flex items-center p-5 md:p-6 bg-white dark:bg-slate-900 border-2 border-slate-100 dark:border-slate-800 rounded-2xl hover:border-primary-500 hover:shadow-xl transition-all active:scale-95">
                  <div className="text-left flex-1">
                    <h3 className="font-bold text-lg text-slate-900 dark:text-white group-hover:text-primary-600">Espace Bénévole</h3>
                    <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Trouver des missions de coeur</p>
                  </div>
                  <Users className="w-7 h-7 text-slate-300 group-hover:text-primary-500" />
                </button>
              </>
            ) : showOrgLogin ? (
              <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2rem] shadow-2xl border border-slate-100 dark:border-slate-800 text-left animate-in fade-in slide-in-from-bottom-4">
                <div className="flex items-center mb-6">
                  <button onClick={() => setShowOrgLogin(false)} className="p-3 mr-3 -ml-2 text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors"><ArrowLeft className="w-6 h-6"/></button>
                  <h3 className="font-black text-xl text-slate-900 dark:text-white">Organisation</h3>
                </div>
                <form onSubmit={handleOrgLoginSubmit} className="space-y-5">
                  <Input label="Email" type="email" placeholder="asso@exemple.com" value={orgLoginData.email} onChange={e => setOrgLoginData({...orgLoginData, email: e.target.value})} required />
                  <Input label="Mot de passe" type="password" value={orgLoginData.password} onChange={e => setOrgLoginData({...orgLoginData, password: e.target.value})} required />
                  <Button type="submit" fullWidth size="lg">Se connecter</Button>
                  <Button type="button" variant="ghost" fullWidth onClick={() => { setShowOrgLogin(false); setIsCreateOrgModalOpen(true); }}>Créer un espace</Button>
                </form>
              </div>
            ) : (
                <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2rem] shadow-2xl border border-slate-100 dark:border-slate-800 text-left animate-in fade-in slide-in-from-bottom-4">
                    <div className="flex items-center mb-6">
                        <button onClick={() => setShowVolunteerLogin(false)} className="p-3 mr-3 -ml-2 text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors"><ArrowLeft className="w-6 h-6"/></button>
                        <h3 className="font-black text-xl text-slate-900 dark:text-white">Bénévole</h3>
                    </div>
                    <form onSubmit={handleVolunteerLoginSubmit} className="space-y-5">
                        <Input label="Pseudo / Identifiant" type="text" placeholder="Ex: vs827" value={volunteerLoginData.username} onChange={e => setVolunteerLoginData({...volunteerLoginData, username: e.target.value})} required />
                        <Input label="Mot de passe" type="password" value={volunteerLoginData.password} onChange={e => setVolunteerLoginData({...volunteerLoginData, password: e.target.value})} required />
                        <Button type="submit" fullWidth size="lg">Se connecter</Button>
                        <Button type="button" variant="ghost" fullWidth onClick={() => { setShowVolunteerLogin(false); setIsCreateVolunteerModalOpen(true); }}>Devenir bénévole</Button>
                    </form>
                </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  // 2. MAIN VIEWS (Organizer & Volunteer)
  return (
