                                  <div className="flex flex-col"><p className="font-bold text-sm md:text-base">{org.name}</p>{isActive && <span className="text-[10px] font-black uppercase tracking-widest text-primary-600">Active</span>}</div>
                              </div>
                              <div className="flex gap-2">
                                  {!isActive && <Button size="sm" variant="secondary" onClick={() => handleSwitchOrganization(org.id)}>Aller</Button>}
                                  <button onClick={() => handleLeaveOrganization(org.id)} className="p-3 text-slate-400 hover:text-red-500 rounded-xl transition-colors"><LogOut className="w-5 h-5" /></button>
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>
      </Modal>

      <Modal isOpen={isMissionModalOpen} onClose={() => setIsMissionModalOpen(false)} title={missionFormData.id ? "Editer" : "Nouvelle Mission"}>
          <div className="space-y-6">
            <Input label="Titre" value={missionFormData.title} onChange={e => setMissionFormData({...missionFormData, title: e.target.value})} />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               <Input label="Début" type="datetime-local" value={missionFormData.dateStart} onChange={e => setMissionFormData({...missionFormData, dateStart: e.target.value})} />
               <Input label="Fin" type="datetime-local" value={missionFormData.dateEnd || ''} onChange={e => setMissionFormData({...missionFormData, dateEnd: e.target.value})} />
            </div>
            <Input label="Adresse / Lieu" value={missionFormData.location} onChange={e => setMissionFormData({...missionFormData, location: e.target.value})} />

            {/* GPS Link Section */}
            <div className="bg-slate-50 dark:bg-slate-800/50 p-4 rounded-2xl border border-slate-100 dark:border-slate-800">
                <div className="flex items-center justify-between mb-2">
                    <label className="text-sm font-bold text-slate-700 dark:text-slate-200 flex items-center gap-2">
                        <MapIcon className="w-4 h-4 text-primary-500" /> Géolocalisation
                    </label>
                    {missionFormData.coordinates && (
                        <button onClick={() => setMissionFormData(prev => ({ ...prev, coordinates: undefined }))} className="text-xs text-red-500 font-bold hover:underline">Retirer</button>
                    )}
                </div>
                {missionFormData.coordinates ? (
                    <div className="flex items-center justify-between bg-white dark:bg-slate-900 p-3 rounded-xl border border-primary-200">
                        <span className="text-xs font-mono text-slate-500">Lat: {missionFormData.coordinates.lat.toFixed(4)}, Lng: {missionFormData.coordinates.lng.toFixed(4)}</span>
                        <Button size="sm" variant="secondary" onClick={() => setIsMapPickerOpen(true)}>Modifier</Button>
                    </div>
                ) : (
                    <Button variant="secondary" fullWidth onClick={() => setIsMapPickerOpen(true)} className="flex items-center gap-2">
                        <Plus className="w-4 h-4" /> Ajouter un point sur la carte
                    </Button>
                )}
            </div>

            <div className="flex flex-col gap-3 pt-4">
                <Button fullWidth size="lg" onClick={handleSaveMission}>{missionFormData.id ? "Mettre à jour" : "Lancer la mission"}</Button>
                {missionFormData.id && <Button variant="ghost" className="text-red-500 hover:text-red-600" onClick={handleDeleteMission}>Supprimer définitivement</Button>}
            </div>
          </div>
      </Modal>

      <Modal isOpen={isLogoutModalOpen} onClose={() => setIsLogoutModalOpen(false)} title="Bye bye ?">
          <div className="space-y-6 py-4">
              <p className="text-slate-600 dark:text-slate-400 font-medium text-center text-lg">Prêt à nous quitter pour aujourd'hui ? On se revoit vite !</p>
              <div className="flex flex-col gap-3">
                  <Button variant="danger" size="lg" fullWidth onClick={logout}>Déconnexion</Button>
                  <Button variant="ghost" fullWidth onClick={() => setIsLogoutModalOpen(false)}>Rester ici</Button>
              </div>
          </div>
      </Modal>

      {activeChatMissionId && (
        <ChatDrawer mission={state.missions.find(m => m.id === activeChatMissionId)!} currentUser={state.currentUser!} onClose={() => setActiveChatMissionId(null)} onSendMessage={handleSendMessage} />
      )}
    </div>
  );
}

import React from 'react';
import { X } from 'lucide-react';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
  zIndex?: string; // Optionnel pour gérer les superpositions
}

export const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children, zIndex = "z-50" }) => {
  if (!isOpen) return null;

  return (
    <div className={`fixed inset-0 ${zIndex} flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in`}>
      <div className="bg-white dark:bg-slate-900 rounded-[2rem] shadow-2xl w-full max-w-md overflow-hidden animate-scale-in border border-slate-200 dark:border-slate-800">
        <div className="flex justify-between items-center p-6 border-b border-slate-100 dark:border-slate-800">
          <h3 className="font-black text-xl text-slate-900 dark:text-white">{title}</h3>
          <button 
            onClick={onClose}
            className="p-2 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
        </div>
        <div className="p-6 dark:text-slate-200 max-h-[80vh] overflow-y-auto">
          {children}
        </div>
      </div>
    </div>
  );
};

