  const [missionFormData, setMissionFormData] = useState<Partial<Mission>>({
    id: undefined,
    title: '', location: '', description: '', category: 'Event', dateStart: '', dateEnd: '',
    coordinates: undefined
  });
  const [orgNameInput, setOrgNameInput] = useState('');
  const [createOrgName, setCreateOrgName] = useState('');

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markerRef = useRef<any>(null);

  useEffect(() => {
    const savedSession = localStorage.getItem('bnevo_org_session');
    if (savedSession) {
      try {
        const session = JSON.parse(savedSession);
        if (session.role === 'organizer') {
          setState(prev => ({
            ...prev,
            currentUser: MOCK_USERS.find(u => u.role === 'organizer') || null,
            currentRole: 'organizer',
            currentOrganization: session.organization || prev.managedOrganization,
            managedOrganization: session.organization || prev.managedOrganization
          }));
        }
      } catch (e) {
        console.error("Failed to parse session", e);
        localStorage.removeItem('bnevo_org_session');
      }
    }
  }, []);

  // Map Initialization logic for PICKER
  useEffect(() => {
    if (isMapPickerOpen && mapContainerRef.current && (window as any).L) {
      const L = (window as any).L;
      const initialCoords = missionFormData.coordinates || { lat: 48.8566, lng: 2.3522 }; 

      if (!mapInstanceRef.current) {
        mapInstanceRef.current = L.map(mapContainerRef.current).setView([initialCoords.lat, initialCoords.lng], 13);
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
          attribution: '© OpenStreetMap'
        }).addTo(mapInstanceRef.current);

        mapInstanceRef.current.on('click', (e: any) => {
          const { lat, lng } = e.latlng;
          setMissionFormData(prev => ({ ...prev, coordinates: { lat, lng } }));
          if (markerRef.current) {
            markerRef.current.setLatLng(e.latlng);
          } else {
            markerRef.current = L.marker(e.latlng).addTo(mapInstanceRef.current);
          }
        });
      }

      if (missionFormData.coordinates) {
          if (markerRef.current) markerRef.current.setLatLng([missionFormData.coordinates.lat, missionFormData.coordinates.lng]);
          else markerRef.current = L.marker([missionFormData.coordinates.lat, missionFormData.coordinates.lng]).addTo(mapInstanceRef.current);
      }
    }

    return () => {
      if (!isMapPickerOpen && mapInstanceRef.current) {
        mapInstanceRef.current.remove();
        mapInstanceRef.current = null;
        markerRef.current = null;
      }
    };
  }, [isMapPickerOpen]);

  // Map Viewer logic
  useEffect(() => {
    if (viewingMapMission && mapContainerRef.current && (window as any).L) {
      const L = (window as any).L;
      const coords = viewingMapMission.coordinates!;

      const viewerMap = L.map(mapContainerRef.current).setView([coords.lat, coords.lng], 15);
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap'
      }).addTo(viewerMap);

      L.marker([coords.lat, coords.lng]).addTo(viewerMap)
        .bindPopup(`<b>${viewingMapMission.title}</b><br>${viewingMapMission.location}`).openPopup();

      return () => {
        viewerMap.remove();
      };
    }
  }, [viewingMapMission]);

  const detectLocation = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((position) => {
        const { latitude, longitude } = position.coords;
        setMissionFormData(prev => ({ ...prev, coordinates: { lat: latitude, lng: longitude } }));
        if (mapInstanceRef.current) {
            mapInstanceRef.current.setView([latitude, longitude], 15);
            if (markerRef.current) markerRef.current.setLatLng([latitude, longitude]);
            else markerRef.current = (window as any).L.marker([latitude, longitude]).addTo(mapInstanceRef.current);
        }
      });
    } else {
      alert("La géolocalisation n'est pas supportée par votre navigateur.");
    }
  };

  const toLocalISOString = (date: Date) => {
    const pad = (num: number) => num.toString().padStart(2, '0');
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
  };

  const getDaysInMonth = (date: Date) => {
    const year = date.getFullYear();
    const month = date.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const firstDayObj = new Date(year, month, 1);
    let firstDay = firstDayObj.getDay();
    const offset = firstDay === 0 ? 6 : firstDay - 1;
    return { daysInMonth, offset, year, month };
  };

  const changeMonth = (delta: number) => {
    const newDate = new Date(calendarDate);
    newDate.setMonth(newDate.getMonth() + delta);
    setCalendarDate(newDate);
  };

  const handleCalendarDayClick = (day: number) => {
    const year = calendarDate.getFullYear();
    const month = calendarDate.getMonth();
    const startDate = new Date(year, month, day, 9, 0);
    const endDate = new Date(year, month, day, 12, 0);

    setMissionFormData({
      id: undefined, 
      title: '', 
      location: '', 
      description: '', 
      category: 'Event',
      dateStart: toLocalISOString(startDate),
      dateEnd: toLocalISOString(endDate),
      coordinates: undefined
    });
    setIsMissionModalOpen(true);
  };

  const handleOrgLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (orgLoginData.email && orgLoginData.password) {
      const orgUser = MOCK_USERS.find(u => u.role === 'organizer');
      const orgData = state.managedOrganization;
      setState(prev => ({
        ...prev,
        currentUser: orgUser || null,
        currentRole: 'organizer',
        currentOrganization: orgData
      }));
      setShowOrgLogin(false);
      if (rememberOrg) {
        localStorage.setItem('bnevo_org_session', JSON.stringify({ role: 'organizer', organization: orgData }));
      }
    }
  };

  const handleCreateOrganization = () => {
    if (!createOrgName.trim()) return;
    const newOrg: Organization = {
      id: `org-${Date.now()}`,
      name: createOrgName,
      code: `NEW-${new Date().getFullYear()}`
    };
    const newAdmin: User = {
      id: `admin-${Date.now()}`,
      firstName: 'Admin',
      lastName: createOrgName,
      username: 'admin_new',
      avatar: '',
      role: 'organizer',
      organizationIds: [newOrg.id]
    };
    setState(prev => ({
      ...prev,
      currentUser: newAdmin,
      currentRole: 'organizer',
      currentOrganization: newOrg,
      managedOrganization: newOrg,
      missions: [], 
      users: [...prev.users, newAdmin],
      organizations: [...prev.organizations, newOrg]
    }));
    localStorage.setItem('bnevo_org_session', JSON.stringify({ role: 'organizer', organization: newOrg }));
    setIsCreateOrgModalOpen(false);
    setShowOrgLogin(false);
  };

  const handleVolunteerLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const user = state.users.find(u => 
      u.role === 'volunteer' && 
      u.username.toLowerCase() === volunteerLoginData.username.toLowerCase() &&
      u.password === volunteerLoginData.password
    );
    if (user) {
      let initialOrg: Organization | null = null;
      if (user.organizationIds && user.organizationIds.length > 0) {
        initialOrg = state.organizations.find(o => o.id === user.organizationIds![0]) || null;
      }
      setState(prev => ({ ...prev, currentUser: user, currentRole: 'volunteer', currentOrganization: initialOrg }));
      setShowVolunteerLogin(false);
      setVolunteerLoginData({ username: '', password: '' });
    } else {
      alert("Pseudo ou mot de passe incorrect.");
    }
  };

  const handleCreateVolunteer = () => {
    if (!createVolunteerData.firstName || !createVolunteerData.username || !createVolunteerData.password) return;
    if (state.users.some(u => u.username.toLowerCase() === createVolunteerData.username.toLowerCase())) {
        alert("Ce pseudo est déjà pris.");
        return;
    }
    const newUser: User = {
        id: `u-${Date.now()}`,
        firstName: createVolunteerData.firstName,
        lastName: createVolunteerData.lastName || '',
        username: createVolunteerData.username,
        password: createVolunteerData.password,
        avatar: `https://ui-avatars.com/api/?name=${createVolunteerData.firstName}+${createVolunteerData.lastName || ''}&background=random`, 
        role: 'volunteer',
        interests: [],
        organizationIds: []
    };
    setState(prev => ({ ...prev, users: [...prev.users, newUser], currentUser: newUser, currentRole: 'volunteer', currentOrganization: null }));
    setIsCreateVolunteerModalOpen(false);
    setShowVolunteerLogin(false);
    setIsManageOrgsModalOpen(true);
  };

  const logout = () => {
    setState(prev => ({ ...prev, currentUser: null, currentRole: 'none' }));
    setActiveTab('dashboard');
    setIsLogoutModalOpen(false);
    localStorage.removeItem('bnevo_org_session');
  };

  const handleJoinOrganization = () => {
    if (!joinCodeInput.trim()) return;
    const orgToJoin = state.organizations.find(o => o.code === joinCodeInput.trim());
    if (!orgToJoin) {
      alert("Code organisation invalide.");
      return;
    }
    const updatedUser = {
      ...state.currentUser!,
      organizationIds: [...(state.currentUser?.organizationIds || []), orgToJoin.id]
    };
    setState(prev => ({
      ...prev,
      currentUser: updatedUser,
      currentOrganization: orgToJoin,
      users: prev.users.map(u => u.id === updatedUser.id ? updatedUser : u)
    }));
    setJoinCodeInput('');
  };

  const handleSwitchOrganization = (orgId: string) => {
    const org = state.organizations.find(o => o.id === orgId);
    if (org) setState(prev => ({ ...prev, currentOrganization: org }));
  };

  const handleLeaveOrganization = (orgId: string) => {
    if (!window.confirm("Quitter cette association ?")) return;
    const currentUserId = state.currentUser!.id;
    const updatedMissions = state.missions.map(m => {
      if (m.organizationId === orgId && m.participants.includes(currentUserId)) {
        return { ...m, participants: m.participants.filter(pid => pid !== currentUserId) };
      }
      return m;
    });
    const updatedUser = {
      ...state.currentUser!,
      organizationIds: state.currentUser!.organizationIds?.filter(id => id !== orgId) || []
    };
    const remainingOrgIds = updatedUser.organizationIds;
    let nextOrg = null;
    if (remainingOrgIds.length > 0) nextOrg = state.organizations.find(o => o.id === remainingOrgIds[0]) || null;
    setState(prev => ({
      ...prev,
      missions: updatedMissions,
      users: prev.users.map(u => u.id === currentUserId ? updatedUser : u),
      currentUser: updatedUser,
      currentOrganization: state.currentOrganization?.id === orgId ? nextOrg : prev.currentOrganization
    }));
  };

  const handleSaveProfile = () => {
    if (profileFormData.interests && profileFormData.interests.length < 3) {
      alert("Ajoutez au moins 3 intérêts.");
      return;
    }
    setState(prev => ({
      ...prev,
      currentUser: { ...prev.currentUser!, ...profileFormData } as User,
      users: prev.users.map(u => u.id === prev.currentUser!.id ? { ...u, ...profileFormData } as User : u)
    }));
    setIsProfileModalOpen(false);
  };

  const handleUpdateOrgName = () => {
    if (orgNameInput.trim()) {
      const updatedOrg = { ...state.currentOrganization!, name: orgNameInput };
      setState(prev => ({
        ...prev,
        currentOrganization: updatedOrg,
        managedOrganization: updatedOrg,
        organizations: prev.organizations.map(o => o.id === updatedOrg.id ? updatedOrg : o)
      }));
      setIsOrgNameModalOpen(false);
    }
  };

  const handleDeleteMission = (e: React.MouseEvent) => {
    e.preventDefault();
    if (!missionFormData.id) return;
    if (window.confirm("Supprimer cette mission ?")) {
        setState(prev => ({ ...prev, missions: prev.missions.filter(m => m.id !== missionFormData.id) }));
        setIsMissionModalOpen(false);
    }
  };

  const handleSaveMission = () => {
    if (!missionFormData.title || !missionFormData.dateStart || !state.currentOrganization) return;
    const finalDateEnd = missionFormData.dateEnd || missionFormData.dateStart;
    if (missionFormData.id) {
        setState(prev => ({
            ...prev,
            missions: prev.missions.map(m => m.id === missionFormData.id ? { ...m, ...missionFormData, dateEnd: finalDateEnd } as Mission : m)
        }));
    } else {
        const newMission: Mission = {
            id: `new-${Date.now()}`,
            organizationId: state.currentOrganization.id,
            title: missionFormData.title!,
            location: missionFormData.location || 'À définir',
            coordinates: missionFormData.coordinates,
            dateStart: missionFormData.dateStart!,
            dateEnd: finalDateEnd,
            description: missionFormData.description || '',
            category: (missionFormData.category as any) || 'Event',
            participants: [],
            chatMessages: []
        };
        setState(prev => ({ ...prev, missions: [...prev.missions, newMission] }));
    }
    setIsMissionModalOpen(false);
  };

  const handleMissionAction = (missionId: string) => {
    if (state.currentRole === 'volunteer') {
      setState(prev => {
        const mission = prev.missions.find(m => m.id === missionId);
        if (!mission || !prev.currentUser) return prev;
        const isRegistered = mission.participants.includes(prev.currentUser.id);
        const newParticipants = isRegistered 
            ? mission.participants.filter(id => id !== prev.currentUser!.id)
            : [...mission.participants, prev.currentUser.id];
        return { ...prev, missions: prev.missions.map(m => m.id === missionId ? { ...m, participants: newParticipants } : m) };
      });
    } else {
      const missionToEdit = state.missions.find(m => m.id === missionId);
      if (missionToEdit) {
          setMissionFormData({ ...missionToEdit });
          setIsMissionModalOpen(true);
      }
    }
  };

  const handleSendMessage = (missionId: string, text: string) => {
    if (!state.currentUser) return;
    const newMessage = {
      id: Date.now().toString(),
      userId: state.currentUser.id,
      userName: state.currentUser.firstName,
      userAvatar: state.currentUser.avatar,
      text,
      timestamp: Date.now()
    };
    setState(prev => ({ ...prev, missions: prev.missions.map(m => m.id === missionId ? { ...m, chatMessages: [...m.chatMessages, newMessage] } : m) }));
  };

  // --- UI COMPONENTS ---

  const Header = () => (
    <header className="sticky top-0 z-40 bg-white/90 dark:bg-slate-900/90 backdrop-blur-lg border-b border-slate-200 dark:border-slate-800">
      <div className="max-w-5xl mx-auto px-4 h-16 md:h-20 flex items-center justify-between">
        <div className="flex items-center gap-3">
           <div className="w-9 h-9 md:w-10 md:h-10 bg-primary-600 rounded-xl flex items-center justify-center shadow-lg shadow-primary-200 dark:shadow-none">
             <Heart className="w-5 h-5 text-white fill-current" />
           </div>
           <div className="flex flex-col">
             <span className="font-bold text-base md:text-xl tracking-tight text-slate-900 dark:text-white leading-none">BNEVO</span>
             {state.currentOrganization && (
               <div className="flex items-center gap-1 mt-1 text-[10px] md:text-xs text-slate-500 dark:text-slate-400 font-medium">
                 <span className="truncate max-w-[100px] md:max-w-[200px]">{state.currentOrganization.name}</span>
                 {state.currentRole === 'organizer' && (
                   <button onClick={() => { setOrgNameInput(state.currentOrganization!.name); setIsOrgNameModalOpen(true); }} className="hover:text-primary-600"><Pencil className="w-2.5 h-2.5" /></button>
                 )}
               </div>
             )}
           </div>
        </div>

        <div className="flex items-center gap-2 md:gap-4">
          <div className="flex items-center gap-2 md:gap-3">
             <div className="text-right hidden sm:block">
               {state.currentRole !== 'organizer' && (
                  <p className="text-sm font-bold text-slate-900 dark:text-white leading-none">{state.currentUser?.firstName}</p>
               )}
               <div className="flex items-center justify-end gap-1 mt-1">
                 <p className="text-[10px] text-slate-500 dark:text-slate-400 uppercase tracking-wider font-semibold">
                    {state.currentRole === 'organizer' ? 'Organisateur' : 'Bénévole'}
                 </p>
               </div>
             </div>

             <div className="flex items-center gap-1.5 md:gap-2">
                {state.currentRole === 'organizer' && (
                   <button onClick={() => setIsOrgCodeModalOpen(true)} className="p-2 md:p-2.5 text-primary-600 dark:text-primary-400 bg-primary-50 dark:bg-primary-900/20 rounded-xl hover:scale-105 transition-transform"><Key className="w-4 h-4 md:w-5 md:h-5" /></button>
                )}
                {state.currentRole === 'volunteer' && (
                   <button onClick={() => setIsManageOrgsModalOpen(true)} className="p-2 md:p-2.5 text-primary-600 dark:text-primary-400 bg-primary-50 dark:bg-primary-900/20 rounded-xl hover:scale-105 transition-transform"><Building className="w-4 h-4 md:w-5 md:h-5" /></button>
                )}
                <button onClick={state.currentRole === 'volunteer' ? () => { setProfileFormData({ ...state.currentUser }); setIsProfileModalOpen(true); } : undefined} className="relative active:scale-95 transition-transform">
                    <img src={state.currentUser?.avatar || `https://ui-avatars.com/api/?name=${state.currentUser?.firstName}&background=random`} alt="Profile" className="w-9 h-9 md:w-11 md:h-11 rounded-xl object-cover border-2 border-white dark:border-slate-800 shadow-sm" />
                </button>
             </div>
          </div>
          <button onClick={() => setIsLogoutModalOpen(true)} className="p-2 md:p-2.5 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-950/30 rounded-xl transition-all"><LogOut className="w-5 h-5" /></button>
        </div>
      </div>
    </header>
  );

  if (state.currentRole === 'none') {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50 dark:bg-slate-950">
        <div className="max-w-md w-full text-center space-y-8">
          <div className="mx-auto w-24 h-24 md:w-28 md:h-28 bg-primary-600 rounded-[2rem] flex items-center justify-center shadow-2xl shadow-primary-200 dark:shadow-none animate-bounce-slow">
            <Heart className="w-12 h-12 md:w-14 md:h-14 text-white fill-current" />
          </div>
          <div className="px-4">
            <h1 className="text-4xl md:text-5xl font-black text-slate-900 dark:text-white tracking-tight">BNEVO</h1>
            <p className="mt-4 text-base md:text-lg text-slate-600 dark:text-slate-400 leading-relaxed font-medium">
              Simplifiez la gestion de vos bénévoles. <br className="hidden md:block"/> Libérez votre temps associatif.
            </p>
          </div>

          <div className="grid grid-cols-1 gap-4 pt-8 px-4">
            {!showOrgLogin && !showVolunteerLogin ? (
              <>
                <button onClick={() => setShowOrgLogin(true)} className="group relative flex items-center p-5 md:p-6 bg-white dark:bg-slate-900 border-2 border-slate-100 dark:border-slate-800 rounded-2xl hover:border-primary-500 hover:shadow-xl transition-all active:scale-95">
                  <div className="text-left flex-1">
                    <h3 className="font-bold text-lg text-slate-900 dark:text-white group-hover:text-primary-600">Espace Organisation</h3>
                    <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Plannings, missions et équipes</p>
                  </div>
                  <LayoutDashboard className="w-7 h-7 text-slate-300 group-hover:text-primary-500" />
                </button>
                <button onClick={() => setShowVolunteerLogin(true)} className="group relative flex items-center p-5 md:p-6 bg-white dark:bg-slate-900 border-2 border-slate-100 dark:border-slate-800 rounded-2xl hover:border-primary-500 hover:shadow-xl transition-all active:scale-95">
                  <div className="text-left flex-1">
                    <h3 className="font-bold text-lg text-slate-900 dark:text-white group-hover:text-primary-600">Espace Bénévole</h3>
                    <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Trouver des missions de coeur</p>
                  </div>
                  <Users className="w-7 h-7 text-slate-300 group-hover:text-primary-500" />
                </button>
              </>
            ) : showOrgLogin ? (
              <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2rem] shadow-2xl border border-slate-100 dark:border-slate-800 text-left animate-in fade-in slide-in-from-bottom-4">
                <div className="flex items-center mb-6">
                  <button onClick={() => setShowOrgLogin(false)} className="p-3 mr-3 -ml-2 text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors"><ArrowLeft className="w-6 h-6"/></button>
                  <h3 className="font-black text-xl text-slate-900 dark:text-white">Organisation</h3>
                </div>
                <form onSubmit={handleOrgLoginSubmit} className="space-y-5">
                  <Input label="Email" type="email" placeholder="asso@exemple.com" value={orgLoginData.email} onChange={e => setOrgLoginData({...orgLoginData, email: e.target.value})} required />
                  <Input label="Mot de passe" type="password" value={orgLoginData.password} onChange={e => setOrgLoginData({...orgLoginData, password: e.target.value})} required />
                  <Button type="submit" fullWidth size="lg">Se connecter</Button>
                  <Button type="button" variant="ghost" fullWidth onClick={() => { setShowOrgLogin(false); setIsCreateOrgModalOpen(true); }}>Créer un espace</Button>
                </form>
              </div>
            ) : (
                <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2rem] shadow-2xl border border-slate-100 dark:border-slate-800 text-left animate-in fade-in slide-in-from-bottom-4">
                    <div className="flex items-center mb-6">
                        <button onClick={() => setShowVolunteerLogin(false)} className="p-3 mr-3 -ml-2 text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors"><ArrowLeft className="w-6 h-6"/></button>
                        <h3 className="font-black text-xl text-slate-900 dark:text-white">Bénévole</h3>
                    </div>
                    <form onSubmit={handleVolunteerLoginSubmit} className="space-y-5">
                        <Input label="Pseudo / Identifiant" type="text" placeholder="Ex: vs827" value={volunteerLoginData.username} onChange={e => setVolunteerLoginData({...volunteerLoginData, username: e.target.value})} required />
                        <Input label="Mot de passe" type="password" value={volunteerLoginData.password} onChange={e => setVolunteerLoginData({...volunteerLoginData, password: e.target.value})} required />
                        <Button type="submit" fullWidth size="lg">Se connecter</Button>
                        <Button type="button" variant="ghost" fullWidth onClick={() => { setShowVolunteerLogin(false); setIsCreateVolunteerModalOpen(true); }}>Devenir bénévole</Button>
                    </form>
                </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white pb-24 md:pb-8">
      <Header />

      {/* Mobile Tab Navigation */}
      <div className="md:hidden fixed bottom-6 left-1/2 -translate-x-1/2 bg-white/90 dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 p-1.5 flex gap-1 rounded-2xl z-30 shadow-2xl backdrop-blur-md">
         {state.currentRole === 'volunteer' ? (
           <>
             <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-3 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-primary-600 text-white shadow-lg' : 'text-slate-400'}`}>
               <LayoutDashboard className="w-5 h-5" />
               <span className="text-sm font-bold">Accueil</span>
             </button>
             <button onClick={() => setActiveTab('calendar')} className={`flex items-center gap-2 px-6 py-3 rounded-xl transition-all ${activeTab === 'calendar' ? 'bg-primary-600 text-white shadow-lg' : 'text-slate-400'}`}>
               <Search className="w-5 h-5" />
               <span className="text-sm font-bold">Explorer</span>
             </button>
           </>
         ) : (
           <>
             <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-5 py-3 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-primary-600 text-white shadow-lg' : 'text-slate-400'}`}>
               <BarChart3 className="w-5 h-5" />
               <span className="text-sm font-bold">Stats</span>
             </button>
             <button onClick={() => setActiveTab('calendar')} className={`flex items-center gap-2 px-5 py-3 rounded-xl transition-all ${activeTab === 'calendar' ? 'bg-primary-600 text-white shadow-lg' : 'text-slate-400'}`}>
               <CalendarIcon className="w-5 h-5" />
               <span className="text-sm font-bold">Planning</span>
             </button>
             <button onClick={() => setActiveTab('missions')} className={`flex items-center gap-2 px-5 py-3 rounded-xl transition-all ${activeTab === 'missions' ? 'bg-primary-600 text-white shadow-lg' : 'text-slate-400'}`}>
               <ListTodo className="w-5 h-5" />
               <span className="text-sm font-bold">Gestion</span>
             </button>
           </>
         )}
      </div>

      <main className="max-w-5xl mx-auto px-4 py-6 md:py-10">
        {state.currentRole === 'organizer' ? (
          <div className="space-y-8">

            {/* ORGANIZER VIEWS */}
            {(activeTab === 'dashboard' || !window.matchMedia("(max-width: 768px)").matches) && (
              <div className={`space-y-8 ${activeTab !== 'dashboard' ? 'hidden md:block' : ''}`}>
                <section className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-5">
                   {[
                     { label: 'Missions', val: state.missions.filter(m => m.organizationId === state.currentOrganization?.id).length, color: 'text-slate-900 dark:text-white' },
                     { label: 'Bénévoles', val: state.users.filter(u => u.role === 'volunteer' && u.organizationIds?.includes(state.currentOrganization!.id)).length, color: 'text-slate-900 dark:text-white' },
                     { label: 'Présences', val: state.missions.filter(m => m.organizationId === state.currentOrganization?.id).reduce((acc, m) => acc + m.participants.length, 0), color: 'text-primary-600' }
                   ].map((s, i) => (
                     <div key={i} className="bg-white dark:bg-slate-900 p-5 md:p-6 rounded-[1.5rem] shadow-sm border border-slate-100 dark:border-slate-800">
                        <p className="text-slate-500 dark:text-slate-400 text-[10px] md:text-xs font-bold uppercase tracking-widest mb-1">{s.label}</p>
                        <p className={`text-2xl md:text-3xl font-black ${s.color}`}>{s.val}</p>
                     </div>
                   ))}
                   <button onClick={() => { setMissionFormData({ id: undefined, title: '', location: '', description: '', category: 'Event', dateStart: toLocalISOString(new Date()), dateEnd: '', coordinates: undefined }); setIsMissionModalOpen(true); }}
                           className="bg-primary-600 p-5 md:p-6 rounded-[1.5rem] shadow-lg shadow-primary-200 dark:shadow-none flex flex-col justify-center items-center cursor-pointer hover:bg-primary-700 active:scale-95 transition-all text-white">
                      <Plus className="w-8 h-8 mb-1" />
                      <p className="font-bold text-[10px] uppercase tracking-wider">Nouvelle Mission</p>
                   </button>
                </section>
                <section className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] border border-slate-100 dark:border-slate-800">
                    <h2 className="text-xl font-black mb-6">Aperçu de l'activité</h2>
                    <p className="text-slate-500 dark:text-slate-400">Gérez vos missions avec précision grâce à la nouvelle fonctionnalité de géolocalisation.</p>
                </section>
              </div>
            )}

            {(activeTab === 'calendar' || !window.matchMedia("(max-width: 768px)").matches) && (
              <section className={`bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2rem] shadow-sm border border-slate-100 dark:border-slate-800 ${activeTab !== 'calendar' ? 'hidden md:block' : ''}`}>
                <div className="flex items-center justify-between mb-8">
                  <h2 className="text-xl font-black flex items-center gap-3">
                    <CalendarIcon className="w-6 h-6 text-primary-500" /> Calendrier
                  </h2>
                  <div className="flex items-center bg-slate-100 dark:bg-slate-800 p-1.5 rounded-xl">
                     <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-white dark:hover:bg-slate-700 rounded-lg transition-all shadow-sm"><ChevronLeft className="w-4 h-4" /></button>
                     <span className="px-4 font-bold capitalize text-xs md:text-sm min-w-[120px] text-center">{calendarDate.toLocaleString('fr-FR', { month: 'long', year: 'numeric' })}</span>
                     <button onClick={() => changeMonth(1)} className="p-2 hover:bg-white dark:hover:bg-slate-700 rounded-lg transition-all shadow-sm"><ChevronRight className="w-4 h-4" /></button>
                  </div>
                </div>
                <div className="grid grid-cols-7 gap-2 mb-4">
                  {['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'].map(d => (
                    <div key={d} className="text-center text-[10px] md:text-xs font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">{d}</div>
                  ))}
                </div>
                <div className="grid grid-cols-7 gap-2 md:gap-3">
                  {Array.from({ length: getDaysInMonth(calendarDate).offset }).map((_, i) => <div key={i} />)}
                  {Array.from({ length: getDaysInMonth(calendarDate).daysInMonth }).map((_, i) => {
                    const day = i + 1;
                    const isToday = new Date().toDateString() === new Date(calendarDate.getFullYear(), calendarDate.getMonth(), day).toDateString();
                    const hasM = state.missions.filter(m => m.organizationId === state.currentOrganization?.id).some(m => {
                        const d = new Date(calendarDate.getFullYear(), calendarDate.getMonth(), day);
                        return d >= new Date(new Date(m.dateStart).setHours(0,0,0,0)) && d <= new Date(new Date(m.dateEnd || m.dateStart).setHours(23,59,59,999));
                    });
                    return (
                      <button key={day} onClick={() => handleCalendarDayClick(day)}
                              className={`h-12 md:h-20 rounded-2xl flex items-center justify-center text-sm md:text-lg font-bold transition-all border-2
                                ${hasM ? 'bg-primary-600 text-white border-primary-500 shadow-lg shadow-primary-100' : 'bg-slate-50 dark:bg-slate-800/50 border-transparent hover:border-primary-300'}
                                ${isToday ? 'ring-2 ring-primary-500 ring-offset-4 dark:ring-offset-slate-900' : ''}`}>
                        {day}
                      </button>
                    );
                  })}
                </div>
              </section>
            )}

            {(activeTab === 'missions' || !window.matchMedia("(max-width: 768px)").matches) && (
              <section className={activeTab !== 'missions' ? 'hidden md:block' : ''}>
                <h2 className="text-2xl font-black mb-6 flex items-center gap-3">Gestion des Missions</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {state.missions.filter(m => m.organizationId === state.currentOrganization?.id).map(m => (
                    <MissionCard key={m.id} mission={m} role="organizer" currentUser={state.currentUser} allUsers={state.users} onAction={handleMissionAction} onChat={setActiveChatMissionId} onViewParticipants={setViewingParticipantsMissionId} onViewMap={setViewingMapMission} />
                  ))}
                </div>
              </section>
            )}
          </div>
        ) : (
          <div className="space-y-10">
            {/* VOLUNTEER VIEWS */}
            {activeTab === 'dashboard' && (
              <>
                {!state.currentOrganization ? (
                   <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-10 text-center border-2 border-slate-100 dark:border-slate-800 shadow-2xl">
                      <div className="w-20 h-20 bg-primary-100 dark:bg-primary-900/30 rounded-[1.5rem] flex items-center justify-center mx-auto mb-6"><Building className="w-10 h-10 text-primary-600" /></div>
                      <h2 className="text-2xl font-black mb-3">Prêt pour l'aventure ?</h2>
                      <p className="text-slate-500 dark:text-slate-400 mb-8 max-w-xs mx-auto text-base">Rejoignez votre première association pour commencer à aider.</p>
                      <Button onClick={() => setIsManageOrgsModalOpen(true)} size="lg">Rejoindre maintenant</Button>
                   </div>
                ) : (
                  <>
                    <div className="bg-gradient-to-br from-primary-600 to-emerald-500 dark:from-primary-700 dark:to-emerald-600 rounded-[2.5rem] p-8 md:p-10 text-white shadow-2xl shadow-primary-200 dark:shadow-none relative overflow-hidden">
                      <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -translate-y-1/2 translate-x-1/2" />
                      <div className="relative z-10">
                        <h2 className="text-3xl md:text-4xl font-black mb-3">Salut {state.currentUser?.firstName} ! 👋</h2>
                        <p className="text-white/80 font-medium mb-8 text-lg">Chez <strong>{state.currentOrganization.name}</strong>, on compte sur toi.</p>
                        <div className="flex gap-4 max-w-sm">
                          <div className="bg-white/20 backdrop-blur-md rounded-2xl px-6 py-4 flex-1"><span className="block text-2xl font-black leading-none">{state.missions.filter(m => m.organizationId === state.currentOrganization?.id && m.participants.includes(state.currentUser!.id)).length}</span><span className="text-[10px] uppercase tracking-wider font-bold opacity-70">Missions</span></div>
                          <div className="bg-white/20 backdrop-blur-md rounded-2xl px-6 py-4 flex-1"><span className="block text-2xl font-black leading-none">12h</span><span className="text-[10px] uppercase tracking-wider font-bold opacity-70">Solidaires</span></div>
                        </div>
                      </div>
                    </div>
                    <section>
                      <h3 className="text-2xl font-black mb-6 flex items-center gap-3"><CalendarIcon className="w-7 h-7 text-primary-500" /> Mon Planning</h3>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {state.missions.filter(m => m.organizationId === state.currentOrganization?.id && m.participants.includes(state.currentUser!.id)).map(m => (
                          <MissionCard key={m.id} mission={m} role="volunteer" currentUser={state.currentUser} allUsers={state.users} onAction={handleMissionAction} onChat={setActiveChatMissionId} onViewParticipants={setViewingParticipantsMissionId} onViewMap={setViewingMapMission} />
                        ))}
                      </div>
                    </section>
                  </>
                )}
              </>
            )}

            {(activeTab === 'calendar' || activeTab === 'dashboard') && state.currentOrganization && (
              <section className={activeTab === 'dashboard' ? 'hidden md:block' : ''}>
                 <h3 id="available-missions" className="text-2xl font-black mb-6 flex items-center gap-3"><Search className="w-7 h-7 text-primary-500" /> Explorer</h3>
                 <div className="flex gap-3 overflow-x-auto pb-6 scrollbar-hide -mx-4 px-4">
                   {['Tout', 'Social', 'Maintenance', 'Event', 'Autre'].map(cat => (
                     <button key={cat} onClick={() => setSelectedCategory(cat)} 
                             className={`px-6 py-3 rounded-2xl text-sm font-bold whitespace-nowrap transition-all border-2 active:scale-95
                               ${selectedCategory === cat ? 'bg-slate-900 dark:bg-white text-white dark:text-slate-900 border-slate-900 dark:border-white shadow-xl' : 'bg-white dark:bg-slate-800 text-slate-500 dark:text-slate-400 border-slate-100 dark:border-slate-700'}`}>{cat}</button>
                   ))}
                 </div>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   {state.missions.filter(m => m.organizationId === state.currentOrganization?.id && !m.participants.includes(state.currentUser!.id) && (selectedCategory === 'Tout' || m.category === selectedCategory)).map(m => (
                      <MissionCard key={m.id} mission={m} role="volunteer" currentUser={state.currentUser} allUsers={state.users} onAction={handleMissionAction} onChat={setActiveChatMissionId} onViewParticipants={setViewingParticipantsMissionId} onViewMap={setViewingMapMission} />
                   ))}
                 </div>
              </section>
            )}
          </div>
        )}
      </main>

      {/* --- MODALS --- */}

      {/* Participants Modal */}
      <Modal isOpen={!!viewingParticipantsMissionId} onClose={() => setViewingParticipantsMissionId(null)} title="Bénévoles Inscrits">
          <div className="space-y-4">
              {state.missions.find(m => m.id === viewingParticipantsMissionId)?.participants.length === 0 ? (
                  <p className="text-center text-slate-500 py-4 font-medium">Aucun bénévole inscrit pour le moment.</p>
              ) : (
                  <div className="space-y-3">
                      {state.missions.find(m => m.id === viewingParticipantsMissionId)?.participants.map(pid => {
                          const user = state.users.find(u => u.id === pid);
                          if (!user) return null;
                          return (
                              <div key={user.id} className="flex items-center gap-4 p-3 bg-slate-50 dark:bg-slate-800/50 rounded-2xl border border-slate-100 dark:border-slate-800 transition-all hover:border-primary-200">
                                  <img src={user.avatar} alt={user.firstName} className="w-12 h-12 rounded-xl object-cover border-2 border-white dark:border-slate-700" />
                                  <div className="flex-1">
                                      <p className="font-bold text-slate-900 dark:text-white leading-none">{user.firstName} {user.lastName}</p>
                                      <p className="text-xs text-slate-500 mt-1">@{user.username}</p>
                                  </div>
                              </div>
                          );
                      })}
                  </div>
              )}
              <Button fullWidth onClick={() => setViewingParticipantsMissionId(null)}>Fermer</Button>
          </div>
      </Modal>

      {/* Map Viewer Modal (Volunteer & Organizer View) */}
      <Modal isOpen={!!viewingMapMission} onClose={() => setViewingMapMission(null)} title={`Lieu : ${viewingMapMission?.title}`}>
          <div className="space-y-4">
              <div className="flex items-center gap-3 p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl border border-slate-100 dark:border-slate-800">
                  <MapPin className="w-5 h-5 text-primary-500" />
                  <p className="font-bold text-slate-900 dark:text-white">{viewingMapMission?.location}</p>
              </div>
              <div ref={mapContainerRef} className="h-72 md:h-96 w-full rounded-[1.5rem] border-2 border-slate-100 dark:border-slate-800 shadow-inner" />
              <Button fullWidth onClick={() => setViewingMapMission(null)}>Fermer</Button>
          </div>
      </Modal>

      {/* Mission Form Modal (Create/Edit) */}
      <Modal isOpen={isMissionModalOpen} onClose={() => setIsMissionModalOpen(false)} title={missionFormData.id ? "Editer la Mission" : "Nouvelle Mission"}>
          <div className="space-y-6">
            <Input label="Titre de la mission" value={missionFormData.title} onChange={e => setMissionFormData({...missionFormData, title: e.target.value})} placeholder="Ex: Ramassage plage" />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               <Input label="Date & Heure Début" type="datetime-local" value={missionFormData.dateStart} onChange={e => setMissionFormData({...missionFormData, dateStart: e.target.value})} />
               <Input label="Date & Heure Fin" type="datetime-local" value={missionFormData.dateEnd || ''} onChange={e => setMissionFormData({...missionFormData, dateEnd: e.target.value})} />
            </div>
            <Input label="Adresse précise / Point de RDV" value={missionFormData.location} onChange={e => setMissionFormData({...missionFormData, location: e.target.value})} placeholder="Ex: 42 rue des fleurs, 75000" />

            {/* GPS Section */}
            <div className="bg-slate-50 dark:bg-slate-800/50 p-5 rounded-[1.5rem] border border-slate-100 dark:border-slate-800">
                <div className="flex items-center justify-between mb-3">
                    <label className="text-sm font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">
                        <MapIcon className="w-4 h-4 text-primary-500" /> Localisation GPS
                    </label>
                    {missionFormData.coordinates && (
                        <button onClick={() => setMissionFormData(prev => ({ ...prev, coordinates: undefined }))} className="text-xs text-red-500 font-bold hover:underline">Supprimer</button>
                    )}
                </div>
                {missionFormData.coordinates ? (
                    <div className="flex items-center justify-between bg-white dark:bg-slate-900 p-4 rounded-xl border border-primary-200">
                        <div className="flex flex-col">
                           <span className="text-xs font-mono text-slate-500">Lat: {missionFormData.coordinates.lat.toFixed(4)}</span>
                           <span className="text-xs font-mono text-slate-500">Lng: {missionFormData.coordinates.lng.toFixed(4)}</span>
                        </div>
                        <div className="flex gap-2">
                            <Button size="sm" variant="secondary" onClick={() => setIsMapPickerOpen(true)}>Modifier</Button>
                            <Button size="sm" variant="ghost" onClick={() => { setViewingMapMission(missionFormData as Mission); }}>Tester</Button>
                        </div>
                    </div>
                ) : (
                    <Button variant="secondary" fullWidth onClick={() => setIsMapPickerOpen(true)} className="flex items-center gap-2">
                        <Plus className="w-4 h-4" /> Placer un point sur la carte
                    </Button>
                )}
            </div>

            <div className="flex flex-col gap-3 pt-4">
                <Button fullWidth size="lg" onClick={handleSaveMission}>{missionFormData.id ? "Mettre à jour" : "Lancer la mission"}</Button>
                {missionFormData.id && <Button variant="ghost" className="text-red-500 hover:text-red-600" onClick={handleDeleteMission}>Supprimer définitivement</Button>}
            </div>
          </div>
      </Modal>

      {/* Map Picker Modal (Organizer, Sub-Modal) */}
      <Modal isOpen={isMapPickerOpen} onClose={() => setIsMapPickerOpen(false)} title="Point de rendez-vous" zIndex="z-[60]">
        <div className="space-y-4">
          <p className="text-sm text-slate-500 font-medium">Cliquez précisément sur le point de rencontre pour les bénévoles.</p>
          <div ref={mapContainerRef} className="h-72 md:h-96 w-full rounded-[1.5rem] border-2 border-slate-100 dark:border-slate-800 shadow-inner" />
          <div className="flex gap-3">
             <Button variant="secondary" fullWidth onClick={detectLocation} className="flex items-center gap-2">
                <Navigation className="w-4 h-4" /> Ma position
             </Button>
             <Button fullWidth onClick={() => setIsMapPickerOpen(false)}>Enregistrer ce point</Button>
          </div>
        </div>
      </Modal>

      <Modal isOpen={isOrgCodeModalOpen} onClose={() => setIsOrgCodeModalOpen(false)} title="Code Association">
          <div className="flex flex-col items-center py-6">
              <div className="w-24 h-24 bg-primary-100 dark:bg-primary-900/30 rounded-[2rem] flex items-center justify-center mb-8"><Key className="w-12 h-12 text-primary-600" /></div>
              <p className="text-center text-slate-500 dark:text-slate-400 mb-6 text-sm md:text-base font-medium">Partagez ce code avec votre équipe pour qu'ils vous rejoignent.</p>
              <div className="w-full bg-slate-100 dark:bg-slate-800 px-8 py-5 rounded-[1.5rem] border-2 border-slate-200 dark:border-slate-700 flex flex-col items-center">
                  <span className="text-4xl font-black tracking-[0.2em] text-slate-900 dark:text-white font-mono">{state.currentOrganization?.code}</span>
              </div>
          </div>
      </Modal>

      <Modal isOpen={isManageOrgsModalOpen} onClose={() => setIsManageOrgsModalOpen(false)} title="Mes Associations">
          <div className="space-y-8">
              <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-[1.5rem] border-2 border-slate-100 dark:border-slate-700">
                  <h4 className="text-sm font-black uppercase tracking-widest text-slate-400 mb-4">Rejoindre</h4>
                  <div className="flex flex-col gap-3">
                      <Input placeholder="Entrez le code ici..." value={joinCodeInput} onChange={e => setJoinCodeInput(e.target.value)} />
                      <Button onClick={handleJoinOrganization} disabled={!joinCodeInput.trim()} fullWidth size="lg">Ajouter</Button>
                  </div>
              </div>
              <div className="space-y-3">
                  <h4 className="text-sm font-black uppercase tracking-widest text-slate-400 ml-1">Liste</h4>
                  {state.currentUser?.organizationIds?.map(orgId => {
                      const org = state.organizations.find(o => o.id === orgId);
                      if (!org) return null;
                      const isActive = state.currentOrganization?.id === orgId;
                      return (
                          <div key={org.id} className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all ${isActive ? 'border-primary-500 bg-primary-50/50 dark:bg-primary-900/10 shadow-lg shadow-primary-50' : 'border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900'}`}>
                              <div className="flex items-center gap-4 flex-1">
                                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${isActive ? 'bg-primary-600 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}`}><Building className="w-5 h-5" /></div>
                                  <div className="flex flex-col"><p className="font-bold text-sm md:text-base">{org.name}</p>{isActive && <span className="text-[10px] font-black uppercase tracking-widest text-primary-600">Active</span>}</div>
                              </div>
                              <div className="flex gap-2">
                                  {!isActive && <Button size="sm" variant="secondary" onClick={() => handleSwitchOrganization(org.id)}>Aller</Button>}
                                  <button onClick={() => handleLeaveOrganization(org.id)} className="p-3 text-slate-400 hover:text-red-500 rounded-xl transition-colors"><LogOut className="w-5 h-5" /></button>
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>
      </Modal>

      <Modal isOpen={isLogoutModalOpen} onClose={() => setIsLogoutModalOpen(false)} title="Bye bye ?">
          <div className="space-y-6 py-4">
              <p className="text-slate-600 dark:text-slate-400 font-medium text-center text-lg">Prêt à nous quitter pour aujourd'hui ? On se revoit vite !</p>
              <div className="flex flex-col gap-3">
                  <Button variant="danger" size="lg" fullWidth onClick={logout}>Déconnexion</Button>
                  <Button variant="ghost" fullWidth onClick={() => setIsLogoutModalOpen(false)}>Rester ici</Button>
              </div>
          </div>
      </Modal>

      {activeChatMissionId && (
        <ChatDrawer mission={state.missions.find(m => m.id === activeChatMissionId)!} currentUser={state.currentUser!} onClose={() => setActiveChatMissionId(null)} onSendMessage={handleSendMessage} />
      )}
    </div>
  );
}

export type Role = 'none' | 'organizer' | 'volunteer';

export interface User {
  id: string;
  firstName: string;
  lastName: string;
  avatar: string; // URL or Initials
  role: Role;
  username: string; // Remplace l'email comme identifiant principal
  email?: string; // Devient optionnel
  password?: string;
  interests?: string[];
  organizationIds?: string[]; // IDs des organisations auxquelles l'utilisateur appartient
}

export interface ChatMessage {
  id: string;
  userId: string;
  userName: string;
  userAvatar: string;
  text: string;
  timestamp: number;
}

export interface MissionObjective {
  id: string;
  title: string;
  lat: number;
  lng: number;
}

export interface Mission {
  id: string;
  organizationId: string; // Lien vers l'organisation
  title: string;
  location: string;
  objectives?: MissionObjective[]; // Liste d'objectifs géolocalisés
  dateStart: string; // ISO Date string
  dateEnd: string;   // ISO Date string
  description: string;
  participants: string[]; // User IDs
  maxParticipants?: number;
  chatMessages: ChatMessage[];
  category: 'Event' | 'Maintenance' | 'Admin' | 'Social' | 'Autre';
}

export interface Organization {
  id: string;
  name: string;
  code: string;
}

export interface AppState {
  currentUser: User | null;
  currentRole: Role;
  currentOrganization: Organization | null; // L'organisation actuellement visualisée/gérée
  managedOrganization: Organization; // Legacy, peut être identique à currentOrganization
  missions: Mission[];
  users: User[]; // Mock database of users
  organizations: Organization[]; // Liste de toutes les orgs disponibles (mock DB)
}

import React from 'react';
import { Calendar, MapPin, Users, MessageCircle, Eye, Map as MapIcon, Flag } from 'lucide-react';
import { Mission, User } from '../types';
import { Button } from './ui/Button';

interface MissionCardProps {
  mission: Mission;
  allUsers: User[];
  currentUser: User | null;
  onAction: (missionId: string) => void;
  onChat: (missionId: string) => void;
  onViewParticipants: (missionId: string) => void;
  onViewMap?: (mission: Mission) => void;
  role: 'volunteer' | 'organizer';
}

export const MissionCard: React.FC<MissionCardProps> = ({ 
  mission, 
  allUsers, 
  currentUser, 
  onAction,
  onChat,
  onViewParticipants,
  onViewMap,
  role 
}) => {
  const participants = allUsers.filter(u => mission.participants.includes(u.id));
  const isRegistered = currentUser && mission.participants.includes(currentUser.id);

  const startDate = new Date(mission.dateStart);
  const endDate = mission.dateEnd ? new Date(mission.dateEnd) : startDate;

  const dateStr = startDate.toLocaleDateString('fr-FR', { weekday: 'short', day: 'numeric', month: 'short' });
  const timeStartStr = startDate.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
  const timeEndStr = endDate.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });

  const isSameDay = startDate.toDateString() === endDate.toDateString();
  const showEndDate = mission.dateEnd && startDate.getTime() !== endDate.getTime();

  let dateDisplay = `${dateStr} • ${timeStartStr}`;
  if (showEndDate) {
    if (isSameDay) dateDisplay += ` - ${timeEndStr}`;
    else dateDisplay += ` au ${endDate.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' })} ${timeEndStr}`;
  }

  const getCategoryColor = (cat: string) => {
    switch(cat) {
      case 'Social': return 'bg-purple-100 text-purple-700 dark:bg-purple-900/50 dark:text-purple-300';
      case 'Maintenance': return 'bg-orange-100 text-orange-700 dark:bg-orange-900/50 dark:text-orange-300';
      case 'Event': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/50 dark:text-blue-300';
      default: return 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300';
    }
  };

  const hasObjectives = mission.objectives && mission.objectives.length > 0;

  return (
    <div className="bg-white dark:bg-slate-900 rounded-[1.75rem] p-5 shadow-sm border border-slate-100 dark:border-slate-800 hover:shadow-xl hover:-translate-y-1 transition-all duration-300 flex flex-col h-full active:scale-[0.98] md:active:scale-100">
      <div className="flex justify-between items-start mb-4">
        <span className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest ${getCategoryColor(mission.category)}`}>
          {mission.category}
        </span>
        {role === 'volunteer' && isRegistered && (
          <span className="flex items-center text-primary-600 dark:text-primary-400 text-[10px] font-black uppercase tracking-widest bg-primary-50 dark:bg-primary-900/30 px-3 py-1 rounded-lg">
            Inscrit
          </span>
        )}
      </div>

      <h3 className="text-xl font-black text-slate-900 dark:text-white mb-3 leading-tight flex-grow">{mission.title}</h3>

      <div className="space-y-2 mb-6">
        <div className="flex items-center gap-3 text-sm text-slate-500 dark:text-slate-400 font-medium">
          <Calendar className="w-4 h-4 text-primary-500" />
          <span>{dateDisplay}</span>
        </div>
        <div className="flex items-center justify-between gap-3 text-sm text-slate-500 dark:text-slate-400 font-medium">
          <div className="flex items-center gap-3 truncate">
            <MapPin className="w-4 h-4 text-primary-500 flex-shrink-0" />
            <span className="truncate">{mission.location}</span>
          </div>
          {hasObjectives && (
            <button 
              onClick={() => onViewMap && onViewMap(mission)}
              className="flex-shrink-0 flex items-center gap-1.5 px-2.5 py-1.5 bg-primary-50 dark:bg-primary-900/20 text-primary-600 dark:text-primary-400 rounded-lg hover:scale-105 transition-transform"
              title="Voir les objectifs sur la carte"
            >
              <MapIcon className="w-4 h-4" />
              <span className="text-[10px] font-black">{mission.objectives?.length}</span>
            </button>
          )}
        </div>
      </div>

      <div className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-800/50 rounded-2xl mb-5">
        <div className="flex -space-x-2">
            {participants.slice(0, 3).map((p) => (
                <img key={p.id} src={p.avatar} alt={p.firstName} className="w-8 h-8 rounded-xl border-2 border-white dark:border-slate-800 object-cover" />
            ))}
            {participants.length > 3 && (
                <div className="w-8 h-8 rounded-xl bg-slate-200 dark:bg-slate-700 flex items-center justify-center text-[10px] font-black">+{participants.length - 3}</div>
            )}
            {participants.length === 0 && <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider ml-2">Vide</span>}
        </div>
        <button onClick={() => onViewParticipants(mission.id)} className="p-2 text-slate-400 hover:text-primary-600 transition-colors">
            <Eye className="w-5 h-5" />
        </button>
      </div>

      <div className="flex items-center gap-2 mt-auto">
        <div className="flex-1">
          <Button 
            variant={role === 'organizer' ? 'secondary' : (isRegistered ? 'secondary' : 'primary')} 
            fullWidth 
            size="md"
            onClick={() => onAction(mission.id)}
          >
            {role === 'organizer' ? 'Gérer' : (isRegistered ? 'Se retirer' : 'Participer')}
          </Button>
        </div>
        <button 
          onClick={() => onChat(mission.id)}
          className="p-3 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:text-primary-600 rounded-xl transition-all active:scale-90"
        >
          <MessageCircle className="w-6 h-6" />
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Users, Calendar as CalendarIcon, LogOut, Plus, 
  BarChart3, LayoutDashboard, Heart, Search, Settings, Pencil, X,
  ChevronLeft, ChevronRight, Building, Tag, Eye, Key, Copy, CheckCircle,
  ArrowLeft, ListTodo, Map as MapIcon, Navigation, MapPin, ExternalLink, Flag, Trash2
} from 'lucide-react';
import { BarChart, Bar, XAxis, Tooltip as RechartsTooltip, ResponsiveContainer, Cell } from 'recharts';

import { MissionCard } from './components/MissionCard';
import { ChatDrawer } from './components/ChatDrawer';
import { Button } from './components/ui/Button';
import { Input } from './components/ui/Input';
import { Modal } from './components/ui/Modal';
import { MOCK_MISSIONS, MOCK_USERS, MOCK_ORG, MOCK_ORG_2 } from './constants';
import { AppState, Mission, Role, User, Organization, MissionObjective } from './types';

// --- MAIN APP COMPONENT ---

export default function App() {
  const [state, setState] = useState<AppState>({
    currentUser: null,
    currentRole: 'none',
    currentOrganization: null,
    managedOrganization: MOCK_ORG,
    missions: MOCK_MISSIONS,
    users: MOCK_USERS,
    organizations: [MOCK_ORG, MOCK_ORG_2]
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'calendar' | 'missions' | 'volunteers'>('dashboard');
  const [activeChatMissionId, setActiveChatMissionId] = useState<string | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<string>('Tout');

  const [showOrgLogin, setShowOrgLogin] = useState(false);
  const [showVolunteerLogin, setShowVolunteerLogin] = useState(false);

  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [isMissionModalOpen, setIsMissionModalOpen] = useState(false);
  const [isOrgNameModalOpen, setIsOrgNameModalOpen] = useState(false);
  const [isCreateOrgModalOpen, setIsCreateOrgModalOpen] = useState(false);
  const [isCreateVolunteerModalOpen, setIsCreateVolunteerModalOpen] = useState(false);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

  const [isOrgCodeModalOpen, setIsOrgCodeModalOpen] = useState(false);
  const [isManageOrgsModalOpen, setIsManageOrgsModalOpen] = useState(false);
  const [joinCodeInput, setJoinCodeInput] = useState('');

  const [viewingParticipantsMissionId, setViewingParticipantsMissionId] = useState<string | null>(null);
  const [viewingMapMission, setViewingMapMission] = useState<Mission | null>(null);
  const [isMapPickerOpen, setIsMapPickerOpen] = useState(false);
  const [pickingObjectiveId, setPickingObjectiveId] = useState<string | null>(null);

  const [calendarDate, setCalendarDate] = useState(new Date());

  const [orgLoginData, setOrgLoginData] = useState({ email: '', password: '' });
  const [volunteerLoginData, setVolunteerLoginData] = useState({ username: '', password: '' });
  const [createVolunteerData, setCreateVolunteerData] = useState({ firstName: '', lastName: '', username: '', password: '' });

  const [rememberOrg, setRememberOrg] = useState(false);
  const [profileFormData, setProfileFormData] = useState<Partial<User>>({});

  const [missionFormData, setMissionFormData] = useState<Partial<Mission>>({
    id: undefined,
    title: '', location: '', description: '', category: 'Event', dateStart: '', dateEnd: '',
    objectives: []
  });
  const [orgNameInput, setOrgNameInput] = useState('');
  const [createOrgName, setCreateOrgName] = useState('');

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markerRef = useRef<any>(null);

  useEffect(() => {
    const savedSession = localStorage.getItem('bnevo_org_session');
    if (savedSession) {
      try {
        const session = JSON.parse(savedSession);
        if (session.role === 'organizer') {
          setState(prev => ({
            ...prev,
            currentUser: MOCK_USERS.find(u => u.role === 'organizer') || null,
            currentRole: 'organizer',
            currentOrganization: session.organization || prev.managedOrganization,
            managedOrganization: session.organization || prev.managedOrganization
          }));
        }
      } catch (e) {
        console.error("Failed to parse session", e);
        localStorage.removeItem('bnevo_org_session');
      }
    }
  }, []);

  // Map Initialization logic for PICKER
  useEffect(() => {
    if (isMapPickerOpen && mapContainerRef.current && (window as any).L && pickingObjectiveId) {
      const L = (window as any).L;
      const currentObjective = missionFormData.objectives?.find(o => o.id === pickingObjectiveId);
      const initialCoords = currentObjective ? { lat: currentObjective.lat, lng: currentObjective.lng } : { lat: 48.8566, lng: 2.3522 }; 

      if (!mapInstanceRef.current) {
        mapInstanceRef.current = L.map(mapContainerRef.current).setView([initialCoords.lat, initialCoords.lng], 13);
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
          attribution: '© OpenStreetMap'
        }).addTo(mapInstanceRef.current);

        mapInstanceRef.current.on('click', (e: any) => {
          const { lat, lng } = e.latlng;
          setMissionFormData(prev => ({
            ...prev,
            objectives: prev.objectives?.map(o => 
              o.id === pickingObjectiveId ? { ...o, lat, lng } : o
            )
          }));
          if (markerRef.current) {
            markerRef.current.setLatLng(e.latlng);
          } else {
            markerRef.current = L.marker(e.latlng).addTo(mapInstanceRef.current);
          }
        });
      }

      if (currentObjective) {
          if (markerRef.current) markerRef.current.setLatLng([currentObjective.lat, currentObjective.lng]);
          else markerRef.current = L.marker([currentObjective.lat, currentObjective.lng]).addTo(mapInstanceRef.current);
      }
    }

    return () => {
      if (!isMapPickerOpen && mapInstanceRef.current) {
        mapInstanceRef.current.remove();
        mapInstanceRef.current = null;
        markerRef.current = null;
      }
    };
  }, [isMapPickerOpen, pickingObjectiveId]);

  // Map Viewer logic (Multiple Markers)
  useEffect(() => {
    if (viewingMapMission && mapContainerRef.current && (window as any).L) {
      const L = (window as any).L;
      const objectives = viewingMapMission.objectives || [];

      if (objectives.length === 0) return;

      const viewerMap = L.map(mapContainerRef.current);
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap'
      }).addTo(viewerMap);

      const markers = objectives.map(obj => {
          return L.marker([obj.lat, obj.lng])
            .addTo(viewerMap)
            .bindPopup(`<b>${obj.title}</b><br>${viewingMapMission.location}`);
      });

      const group = new L.featureGroup(markers);
      viewerMap.fitBounds(group.getBounds().pad(0.1));

      return () => {
        viewerMap.remove();
      };
    }
  }, [viewingMapMission]);

  const detectLocation = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((position) => {
        const { latitude, longitude } = position.coords;
        if (pickingObjectiveId) {
            setMissionFormData(prev => ({
                ...prev,
                objectives: prev.objectives?.map(o => 
                    o.id === pickingObjectiveId ? { ...o, lat: latitude, lng: longitude } : o
                )
            }));
            if (mapInstanceRef.current) {
                mapInstanceRef.current.setView([latitude, longitude], 15);
                if (markerRef.current) markerRef.current.setLatLng([latitude, longitude]);
                else markerRef.current = (window as any).L.marker([latitude, longitude]).addTo(mapInstanceRef.current);
            }
        }
      });
    } else {
      alert("La géolocalisation n'est pas supportée par votre navigateur.");
    }
  };

  const toLocalISOString = (date: Date) => {
    const pad = (num: number) => num.toString().padStart(2, '0');
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
  };

  const getDaysInMonth = (date: Date) => {
    const year = date.getFullYear();
    const month = date.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const firstDayObj = new Date(year, month, 1);
    let firstDay = firstDayObj.getDay();
    const offset = firstDay === 0 ? 6 : firstDay - 1;
    return { daysInMonth, offset, year, month };
  };

  const changeMonth = (delta: number) => {
    const newDate = new Date(calendarDate);
    newDate.setMonth(newDate.getMonth() + delta);
    setCalendarDate(newDate);
  };

  const handleCalendarDayClick = (day: number) => {
    const year = calendarDate.getFullYear();
    const month = calendarDate.getMonth();
    const startDate = new Date(year, month, day, 9, 0);
    const endDate = new Date(year, month, day, 12, 0);

    setMissionFormData({
      id: undefined, 
      title: '', 
      location: '', 
      description: '', 
      category: 'Event',
      dateStart: toLocalISOString(startDate),
      dateEnd: toLocalISOString(endDate),
      objectives: []
    });
    setIsMissionModalOpen(true);
  };

  const handleOrgLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (orgLoginData.email && orgLoginData.password) {
      const orgUser = MOCK_USERS.find(u => u.role === 'organizer');
      const orgData = state.managedOrganization;
      setState(prev => ({
        ...prev,
        currentUser: orgUser || null,
        currentRole: 'organizer',
        currentOrganization: orgData
      }));
      setShowOrgLogin(false);
      if (rememberOrg) {
        localStorage.setItem('bnevo_org_session', JSON.stringify({ role: 'organizer', organization: orgData }));
      }
    }
  };

  const handleCreateOrganization = () => {
    if (!createOrgName.trim()) return;
    const newOrg: Organization = {
      id: `org-${Date.now()}`,
      name: createOrgName,
      code: `NEW-${new Date().getFullYear()}`
    };
    const newAdmin: User = {
      id: `admin-${Date.now()}`,
      firstName: 'Admin',
      lastName: createOrgName,
      username: 'admin_new',
      avatar: '',
      role: 'organizer',
      organizationIds: [newOrg.id]
    };
    setState(prev => ({
      ...prev,
      currentUser: newAdmin,
      currentRole: 'organizer',
      currentOrganization: newOrg,
      managedOrganization: newOrg,
      missions: [], 
      users: [...prev.users, newAdmin],
      organizations: [...prev.organizations, newOrg]
    }));
    localStorage.setItem('bnevo_org_session', JSON.stringify({ role: 'organizer', organization: newOrg }));
    setIsCreateOrgModalOpen(false);
    setShowOrgLogin(false);
  };

  const handleVolunteerLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const user = state.users.find(u => 
      u.role === 'volunteer' && 
      u.username.toLowerCase() === volunteerLoginData.username.toLowerCase() &&
      u.password === volunteerLoginData.password
    );
    if (user) {
      let initialOrg: Organization | null = null;
      if (user.organizationIds && user.organizationIds.length > 0) {
        initialOrg = state.organizations.find(o => o.id === user.organizationIds![0]) || null;
      }
      setState(prev => ({ ...prev, currentUser: user, currentRole: 'volunteer', currentOrganization: initialOrg }));
      setShowVolunteerLogin(false);
      setVolunteerLoginData({ username: '', password: '' });
    } else {
      alert("Pseudo ou mot de passe incorrect.");
    }
  };

  const handleCreateVolunteer = () => {
    if (!createVolunteerData.firstName || !createVolunteerData.username || !createVolunteerData.password) return;
    if (state.users.some(u => u.username.toLowerCase() === createVolunteerData.username.toLowerCase())) {
        alert("Ce pseudo est déjà pris.");
        return;
    }
    const newUser: User = {
        id: `u-${Date.now()}`,
        firstName: createVolunteerData.firstName,
        lastName: createVolunteerData.lastName || '',
        username: createVolunteerData.username,
        password: createVolunteerData.password,
        avatar: `https://ui-avatars.com/api/?name=${createVolunteerData.firstName}+${createVolunteerData.lastName || ''}&background=random`, 
        role: 'volunteer',
        interests: [],
        organizationIds: []
    };
    setState(prev => ({ ...prev, users: [...prev.users, newUser], currentUser: newUser, currentRole: 'volunteer', currentOrganization: null }));
    setIsCreateVolunteerModalOpen(false);
    setShowVolunteerLogin(false);
    setIsManageOrgsModalOpen(true);
  };

  const logout = () => {
    setState(prev => ({ ...prev, currentUser: null, currentRole: 'none' }));
    setActiveTab('dashboard');
    setIsLogoutModalOpen(false);
    localStorage.removeItem('bnevo_org_session');
  };

  const handleJoinOrganization = () => {
    if (!joinCodeInput.trim()) return;
    const orgToJoin = state.organizations.find(o => o.code === joinCodeInput.trim());
    if (!orgToJoin) {
      alert("Code organisation invalide.");
      return;
    }
    const updatedUser = {
      ...state.currentUser!,
      organizationIds: [...(state.currentUser?.organizationIds || []), orgToJoin.id]
    };
    setState(prev => ({
      ...prev,
      currentUser: updatedUser,
      currentOrganization: orgToJoin,
      users: prev.users.map(u => u.id === updatedUser.id ? updatedUser : u)
    }));
    setJoinCodeInput('');
  };

  const handleSwitchOrganization = (orgId: string) => {
    const org = state.organizations.find(o => o.id === orgId);
    if (org) setState(prev => ({ ...prev, currentOrganization: org }));
  };

  const handleLeaveOrganization = (orgId: string) => {
    if (!window.confirm("Quitter cette association ?")) return;
    const currentUserId = state.currentUser!.id;
    const updatedMissions = state.missions.map(m => {
      if (m.organizationId === orgId && m.participants.includes(currentUserId)) {
        return { ...m, participants: m.participants.filter(pid => pid !== currentUserId) };
      }
      return m;
    });
    const updatedUser = {
      ...state.currentUser!,
      organizationIds: state.currentUser!.organizationIds?.filter(id => id !== orgId) || []
    };
    const remainingOrgIds = updatedUser.organizationIds;
    let nextOrg = null;
    if (remainingOrgIds.length > 0) nextOrg = state.organizations.find(o => o.id === remainingOrgIds[0]) || null;
    setState(prev => ({
      ...prev,
      missions: updatedMissions,
      users: prev.users.map(u => u.id === currentUserId ? updatedUser : u),
      currentUser: updatedUser,
      currentOrganization: state.currentOrganization?.id === orgId ? nextOrg : prev.currentOrganization
    }));
  };

  const handleSaveProfile = () => {
    setState(prev => ({
      ...prev,
      currentUser: { ...prev.currentUser!, ...profileFormData } as User,
      users: prev.users.map(u => u.id === prev.currentUser!.id ? { ...u, ...profileFormData } as User : u)
    }));
    setIsProfileModalOpen(false);
  };

  const handleUpdateOrgName = () => {
    if (orgNameInput.trim()) {
      const updatedOrg = { ...state.currentOrganization!, name: orgNameInput };
      setState(prev => ({
        ...prev,
        currentOrganization: updatedOrg,
        managedOrganization: updatedOrg,
        organizations: prev.organizations.map(o => o.id === updatedOrg.id ? updatedOrg : o)
      }));
      setIsOrgNameModalOpen(false);
    }
  };

  const handleDeleteMission = (e: React.MouseEvent) => {
    e.preventDefault();
    if (!missionFormData.id) return;
    if (window.confirm("Supprimer cette mission ?")) {
        setState(prev => ({ ...prev, missions: prev.missions.filter(m => m.id !== missionFormData.id) }));
        setIsMissionModalOpen(false);
    }
  };

  const handleSaveMission = () => {
    if (!missionFormData.title || !missionFormData.dateStart || !state.currentOrganization) return;
    const finalDateEnd = missionFormData.dateEnd || missionFormData.dateStart;
    if (missionFormData.id) {
        setState(prev => ({
            ...prev,
            missions: prev.missions.map(m => m.id === missionFormData.id ? { ...m, ...missionFormData, dateEnd: finalDateEnd } as Mission : m)
        }));
    } else {
        const newMission: Mission = {
            id: `new-${Date.now()}`,
            organizationId: state.currentOrganization.id,
            title: missionFormData.title!,
            location: missionFormData.location || 'À définir',
            objectives: missionFormData.objectives,
            dateStart: missionFormData.dateStart!,
            dateEnd: finalDateEnd,
            description: missionFormData.description || '',
            category: (missionFormData.category as any) || 'Event',
            participants: [],
            chatMessages: []
        };
        setState(prev => ({ ...prev, missions: [...prev.missions, newMission] }));
    }
    setIsMissionModalOpen(false);
  };

  const handleMissionAction = (missionId: string) => {
    if (state.currentRole === 'volunteer') {
      setState(prev => {
        const mission = prev.missions.find(m => m.id === missionId);
        if (!mission || !prev.currentUser) return prev;
        const isRegistered = mission.participants.includes(prev.currentUser.id);
        const newParticipants = isRegistered 
            ? mission.participants.filter(id => id !== prev.currentUser!.id)
            : [...mission.participants, prev.currentUser.id];
        return { ...prev, missions: prev.missions.map(m => m.id === missionId ? { ...m, participants: newParticipants } : m) };
      });
    } else {
      const missionToEdit = state.missions.find(m => m.id === missionId);
      if (missionToEdit) {
          setMissionFormData({ ...missionToEdit });
          setIsMissionModalOpen(true);
      }
    }
  };

  const handleSendMessage = (missionId: string, text: string) => {
    if (!state.currentUser) return;
    const newMessage = {
      id: Date.now().toString(),
      userId: state.currentUser.id,
      userName: state.currentUser.firstName,
      userAvatar: state.currentUser.avatar,
      text,
      timestamp: Date.now()
    };
    setState(prev => ({ ...prev, missions: prev.missions.map(m => m.id === missionId ? { ...m, chatMessages: [...m.chatMessages, newMessage] } : m) }));
  };

  const addObjective = () => {
    const newObj: MissionObjective = {
        id: `obj-${Date.now()}`,
        title: '',
        lat: 48.8566,
        lng: 2.3522
    };
    setMissionFormData(prev => ({ ...prev, objectives: [...(prev.objectives || []), newObj] }));
  };

  const removeObjective = (id: string) => {
    setMissionFormData(prev => ({ ...prev, objectives: prev.objectives?.filter(o => o.id !== id) }));
  };

  const updateObjectiveTitle = (id: string, title: string) => {
    setMissionFormData(prev => ({
        ...prev,
        objectives: prev.objectives?.map(o => o.id === id ? { ...o, title } : o)
    }));
  };

  const openPickerForObjective = (id: string) => {
    setPickingObjectiveId(id);
    setIsMapPickerOpen(true);
  };

  // --- UI COMPONENTS ---

  const Header = () => (
    <header className="sticky top-0 z-40 bg-white/90 dark:bg-slate-900/90 backdrop-blur-lg border-b border-slate-200 dark:border-slate-800">
