                              <div className="flex gap-2">
                                  {!isActive && <Button size="sm" variant="secondary" onClick={() => handleSwitchOrganization(org.id)}>Aller</Button>}
                                  <button onClick={() => handleLeaveOrganization(org.id)} className="p-3 text-slate-400 hover:text-red-500 rounded-xl transition-colors"><LogOut className="w-5 h-5" /></button>
