export default function App() {
  const [state, setState] = useState<AppState>({
    currentUser: null,
    currentRole: 'none',
    currentOrganization: null,
    managedOrganization: MOCK_ORG,
    missions: MOCK_MISSIONS,
    users: MOCK_USERS,
    organizations: [MOCK_ORG, MOCK_ORG_2, MOCK_ORG_3, MOCK_ORG_4, MOCK_ORG_5, MOCK_ORG_6, MOCK_ORG_7, MOCK_ORG_8]
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'calendar' | 'missions' | 'organizations' | 'volunteers'>('dashboard');
  const [activeChatMissionId, setActiveChatMissionId] = useState<string | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<string>('Tout');

  const [showOrgLogin, setShowOrgLogin] = useState(false);
  const [showVolunteerLogin, setShowVolunteerLogin] = useState(false);

  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [isMissionModalOpen, setIsMissionModalOpen] = useState(false);
  const [isOrgNameModalOpen, setIsOrgNameModalOpen] = useState(false);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

  const [isOrgCodeModalOpen, setIsOrgCodeModalOpen] = useState(false);
  const [isManageOrgsModalOpen, setIsManageOrgsModalOpen] = useState(false);
  const [isCreateVolunteerModalOpen, setIsCreateVolunteerModalOpen] = useState(false);
  const [joinCodeInput, setJoinCodeInput] = useState('');

  const [viewingParticipantsMissionId, setViewingParticipantsMissionId] = useState<string | null>(null);
  const [viewingMapMission, setViewingMapMission] = useState<Mission | null>(null);
  const [isMapPickerOpen, setIsMapPickerOpen] = useState(false);
  const [pickingObjectiveId, setPickingObjectiveId] = useState<string | null>(null);

  const [calendarDate, setCalendarDate] = useState(new Date());

  const [orgLoginData, setOrgLoginData] = useState({ email: '', password: '' });
  const [volunteerLoginData, setVolunteerLoginData] = useState({ username: '', password: '' });
  const [createVolunteerData, setCreateVolunteerData] = useState({ firstName: '', lastName: '', username: '', password: '' });

  const [rememberOrg, setRememberOrg] = useState(false);
  const [profileFormData, setProfileFormData] = useState<Partial<User>>({});

  const [missionFormData, setMissionFormData] = useState<Partial<Mission>>({
    id: undefined,
    title: '', location: '', description: '', category: 'Event', dateStart: '', dateEnd: '',
    objectives: []
  });

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markerRef = useRef<any>(null);

  // Volunteering Logic
  const joinedOrgIds = state.currentUser?.organizationIds || [];
  const volunteerMissions = state.missions.filter(m => joinedOrgIds.includes(m.organizationId));
  const myMissions = volunteerMissions.filter(m => m.participants.includes(state.currentUser?.id || ''));

  useEffect(() => {
    const savedSession = localStorage.getItem('bnevo_org_session');
    if (savedSession) {
      try {
        const session = JSON.parse(savedSession);
        if (session.role === 'organizer') {
          setState(prev => ({
            ...prev,
            currentUser: MOCK_USERS.find(u => u.role === 'organizer') || null,
            currentRole: 'organizer',
            currentOrganization: session.organization || prev.managedOrganization,
            managedOrganization: session.organization || prev.managedOrganization
          }));
        }
      } catch (e) {
        localStorage.removeItem('bnevo_org_session');
      }
    }
  }, []);

  const handleOrgLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (orgLoginData.email && orgLoginData.password) {
      const orgUser = MOCK_USERS.find(u => u.role === 'organizer');
      const orgData = state.managedOrganization;
      setState(prev => ({
        ...prev,
        currentUser: orgUser || null,
        currentRole: 'organizer',
        currentOrganization: orgData
      }));
      setShowOrgLogin(false);
    }
  };

  const handleVolunteerLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const user = state.users.find(u => 
      u.role === 'volunteer' && 
      u.username.toLowerCase() === volunteerLoginData.username.toLowerCase() &&
      u.password === volunteerLoginData.password
    );
    if (user) {
      setState(prev => ({ ...prev, currentUser: user, currentRole: 'volunteer' }));
      setShowVolunteerLogin(false);
      setActiveTab('dashboard');
    } else {
      alert("Identifiants incorrects.");
    }
  };

  const handleCreateVolunteer = () => {
    if (!createVolunteerData.firstName || !createVolunteerData.username || !createVolunteerData.password) return;
    const newUser: User = {
        id: `u-${Date.now()}`,
        firstName: createVolunteerData.firstName,
        lastName: createVolunteerData.lastName || '',
        username: createVolunteerData.username,
        password: createVolunteerData.password,
        avatar: `https://ui-avatars.com/api/?name=${createVolunteerData.firstName}&background=random`, 
        role: 'volunteer',
        organizationIds: []
    };
    setState(prev => ({ ...prev, users: [...prev.users, newUser], currentUser: newUser, currentRole: 'volunteer' }));
    setIsCreateVolunteerModalOpen(false);
    setShowVolunteerLogin(false);
    setActiveTab('organizations'); // Redirect to explore immediately
  };

  const handleJoinOrganization = (orgId: string) => {
    const orgToJoin = state.organizations.find(o => o.id === orgId);
    if (!orgToJoin) return;

    const updatedUser = {
      ...state.currentUser!,
      organizationIds: Array.from(new Set([...(state.currentUser?.organizationIds || []), orgToJoin.id]))
    };

    setState(prev => ({
      ...prev,
      currentUser: updatedUser,
      users: prev.users.map(u => u.id === updatedUser.id ? updatedUser : u)
    }));
  };

  const handleLeaveOrganization = (orgId: string) => {
    if (!window.confirm("Quitter cette association ?")) return;
    const currentUserId = state.currentUser!.id;
    const updatedUser = {
      ...state.currentUser!,
      organizationIds: state.currentUser!.organizationIds?.filter(id => id !== orgId) || []
    };
    setState(prev => ({
      ...prev,
      users: prev.users.map(u => u.id === currentUserId ? updatedUser : u),
      currentUser: updatedUser
    }));
  };

  const handleMissionAction = (missionId: string) => {
    if (state.currentRole === 'volunteer') {
      setState(prev => {
        const mission = prev.missions.find(m => m.id === missionId);
        if (!mission || !prev.currentUser) return prev;
        const isRegistered = mission.participants.includes(prev.currentUser.id);
        const newParticipants = isRegistered 
            ? mission.participants.filter(id => id !== prev.currentUser!.id)
            : [...mission.participants, prev.currentUser.id];
        return { ...prev, missions: prev.missions.map(m => m.id === missionId ? { ...m, participants: newParticipants } : m) };
      });
    } else {
      const missionToEdit = state.missions.find(m => m.id === missionId);
      if (missionToEdit) {
          setMissionFormData({ ...missionToEdit });
          setIsMissionModalOpen(true);
      }
    }
  };

  const handleSendMessage = (missionId: string, text: string) => {
    const newMessage = {
      id: Date.now().toString(),
      userId: state.currentUser!.id,
      userName: state.currentUser!.firstName,
      userAvatar: state.currentUser!.avatar,
      text,
      timestamp: Date.now()
    };
    setState(prev => ({ ...prev, missions: prev.missions.map(m => m.id === missionId ? { ...m, chatMessages: [...m.chatMessages, newMessage] } : m) }));
  };

  const Header = () => (
    <header className="sticky top-0 z-40 bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 shadow-sm">
      <div className="max-w-5xl mx-auto px-4 h-16 md:h-20 flex items-center justify-between">
        <div className="flex items-center gap-3">
           <div className="w-9 h-9 md:w-10 md:h-10 bg-primary-600 rounded-xl flex items-center justify-center shadow-lg shadow-primary-200">
             <Heart className="w-5 h-5 text-white fill-current" />
           </div>
           <div className="flex flex-col">
             <span className="font-black text-base md:text-xl tracking-tighter text-slate-900 dark:text-white leading-none">BNEVO</span>
             <p className="text-[9px] md:text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Impact Hub</p>
           </div>
        </div>

        {/* Volunteer Segmented Control */}
        {state.currentRole === 'volunteer' && (
          <div className="bg-slate-100 dark:bg-slate-800 p-1 rounded-xl flex items-center shadow-inner">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-tight transition-all ${activeTab === 'dashboard' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-sm' : 'text-slate-500'}`}
            >
              Mon Espace
            </button>
            <button 
              onClick={() => setActiveTab('organizations')}
              className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-tight transition-all ${activeTab === 'organizations' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-sm' : 'text-slate-500'}`}
            >
              Explorer
            </button>
          </div>
        )}

        <div className="flex items-center gap-2 md:gap-4">
          <div className="flex items-center gap-2">
             <div className="text-right hidden sm:block">
               <p className="text-sm font-black text-slate-900 dark:text-white leading-none">{state.currentUser?.firstName}</p>
               <p className="text-[9px] text-slate-400 uppercase tracking-widest font-black mt-1">
                  {state.currentRole === 'organizer' ? 'Organisateur' : 'Bénévole'}
               </p>
             </div>
             <button onClick={() => setIsProfileModalOpen(true)} className="relative active:scale-95 transition-transform">
                <img src={state.currentUser?.avatar} alt="Profile" className="w-9 h-9 md:w-11 md:h-11 rounded-xl object-cover border-2 border-white dark:border-slate-800 shadow-sm" />
             </button>
          </div>
          <button onClick={() => setIsLogoutModalOpen(true)} className="p-2 text-slate-400 hover:text-red-500 transition-colors"><LogOut className="w-5 h-5" /></button>
        </div>
      </div>
    </header>
  );

  if (state.currentRole === 'none') {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50 dark:bg-slate-950">
        <div className="max-w-md w-full text-center space-y-12">
          <div className="mx-auto w-24 h-24 bg-primary-600 rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-primary-200 animate-bounce-slow">
            <Heart className="w-12 h-12 text-white fill-current" />
          </div>
          <div>
            <h1 className="text-5xl font-black text-slate-900 dark:text-white tracking-tighter">BNEVO</h1>
            <p className="mt-4 text-slate-500 dark:text-slate-400 font-medium">L'engagement solidaire, simplifié à l'extrême.</p>
          </div>

          <div className="space-y-4 pt-6">
            {!showOrgLogin && !showVolunteerLogin ? (
              <>
                <Button fullWidth size="lg" onClick={() => setShowVolunteerLogin(true)}>Espace Bénévole</Button>
                <Button variant="secondary" fullWidth size="lg" onClick={() => setShowOrgLogin(true)}>Accès Organisateur</Button>
              </>
            ) : showOrgLogin ? (
              <div className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] shadow-2xl border border-slate-100 text-left animate-in fade-in slide-in-from-bottom-4">
                <button onClick={() => setShowOrgLogin(false)} className="mb-6 flex items-center gap-2 text-slate-400 hover:text-slate-900 font-bold text-sm"><ArrowLeft className="w-4 h-4"/> Retour</button>
                <h3 className="text-2xl font-black mb-6">Connexion Orga</h3>
                <form onSubmit={handleOrgLoginSubmit} className="space-y-5">
                  <Input label="Email" type="email" value={orgLoginData.email} onChange={e => setOrgLoginData({...orgLoginData, email: e.target.value})} required />
                  <Input label="Mot de passe" type="password" value={orgLoginData.password} onChange={e => setOrgLoginData({...orgLoginData, password: e.target.value})} required />
                  <Button type="submit" fullWidth size="lg">Se connecter</Button>
                </form>
              </div>
            ) : (
              <div className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] shadow-2xl border border-slate-100 text-left animate-in fade-in slide-in-from-bottom-4">
                <button onClick={() => setShowVolunteerLogin(false)} className="mb-6 flex items-center gap-2 text-slate-400 hover:text-slate-900 font-bold text-sm"><ArrowLeft className="w-4 h-4"/> Retour</button>
                <h3 className="text-2xl font-black mb-6">Connexion Bénévole</h3>
                <form onSubmit={handleVolunteerLoginSubmit} className="space-y-5">
                  <Input label="Pseudo" value={volunteerLoginData.username} onChange={e => setVolunteerLoginData({...volunteerLoginData, username: e.target.value})} required />
                  <Input label="Mot de passe" type="password" value={volunteerLoginData.password} onChange={e => setVolunteerLoginData({...volunteerLoginData, password: e.target.value})} required />
                  <Button type="submit" fullWidth size="lg">Entrer</Button>
                  <Button variant="ghost" fullWidth onClick={() => setIsCreateVolunteerModalOpen(true)}>Créer un compte</Button>
                </form>
              </div>
            )}
          </div>
        </div>

        <Modal isOpen={isCreateVolunteerModalOpen} onClose={() => setIsCreateVolunteerModalOpen(false)} title="Nouveau Bénévole">
            <form onSubmit={(e) => { e.preventDefault(); handleCreateVolunteer(); }} className="space-y-4">
                <Input label="Prénom" value={createVolunteerData.firstName} onChange={e => setCreateVolunteerData({...createVolunteerData, firstName: e.target.value})} required />
                <Input label="Identifiant" value={createVolunteerData.username} onChange={e => setCreateVolunteerData({...createVolunteerData, username: e.target.value})} required />
                <Input label="Mot de passe" type="password" value={createVolunteerData.password} onChange={e => setCreateVolunteerData({...createVolunteerData, password: e.target.value})} required />
                <Button type="submit" fullWidth size="lg" className="mt-4">S'inscrire</Button>
            </form>
        </Modal>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white pb-24 md:pb-8">
      <Header />

      <main className="max-w-5xl mx-auto px-4 py-6 md:py-10">
        {state.currentRole === 'organizer' ? (
          <div className="space-y-8">
             <section className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {[
                  { label: 'Missions', val: state.missions.filter(m => m.organizationId === state.currentOrganization?.id).length },
                  { label: 'Bénévoles', val: state.users.filter(u => u.organizationIds?.includes(state.currentOrganization?.id || '')).length },
                  { label: 'Participations', val: state.missions.filter(m => m.organizationId === state.currentOrganization?.id).reduce((acc, m) => acc + m.participants.length, 0) }
                ].map((s, i) => (
                  <div key={i} className="bg-white dark:bg-slate-900 p-6 rounded-[1.5rem] border border-slate-100 shadow-sm">
                     <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1">{s.label}</p>
                     <p className="text-3xl font-black">{s.val}</p>
                  </div>
                ))}
                <button onClick={() => setIsMissionModalOpen(true)} className="bg-primary-600 text-white p-6 rounded-[1.5rem] shadow-lg flex flex-col justify-center items-center hover:bg-primary-700 transition-all active:scale-95">
                   <Plus className="w-8 h-8 mb-1" />
                   <p className="font-black text-[10px] uppercase tracking-widest">Nouveau</p>
                </button>
             </section>
             <section className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
               {state.missions.filter(m => m.organizationId === state.currentOrganization?.id).map(m => (
                 <MissionCard key={m.id} mission={m} role="organizer" currentUser={state.currentUser} allUsers={state.users} onAction={handleMissionAction} onChat={setActiveChatMissionId} onViewParticipants={setViewingParticipantsMissionId} onViewMap={() => {}} />
               ))}
             </section>
          </div>
        ) : (
          <div className="space-y-10">
            {activeTab === 'dashboard' && (
              <>
                {joinedOrgIds.length === 0 ? (
                   <div className="bg-white dark:bg-slate-900 rounded-[3rem] p-12 text-center border-2 border-slate-100 dark:border-slate-800 shadow-xl animate-in zoom-in-95">
                      <div className="w-24 h-24 bg-primary-100 dark:bg-primary-900/30 rounded-[2rem] flex items-center justify-center mx-auto mb-8"><Sparkles className="w-12 h-12 text-primary-600" /></div>
                      <h2 className="text-3xl font-black mb-4 tracking-tight">Prêt à faire la différence ?</h2>
                      <p className="text-slate-500 dark:text-slate-400 mb-10 max-w-sm mx-auto text-lg">Rejoignez votre première association pour débloquer votre espace personnel.</p>
                      <Button onClick={() => setActiveTab('organizations')} size="lg" className="px-10">Découvrir les associations</Button>
                   </div>
                ) : (
                  <>
                    <div className="bg-slate-900 dark:bg-primary-900 rounded-[2.5rem] p-8 md:p-12 text-white shadow-2xl relative overflow-hidden group">
                        <div className="absolute top-0 right-0 w-64 h-64 bg-primary-500/10 rounded-full -translate-y-1/2 translate-x-1/2 blur-3xl group-hover:scale-150 transition-transform duration-1000" />
                        <div className="relative z-10">
                            <h2 className="text-4xl md:text-5xl font-black mb-2 tracking-tighter">Tableau de bord</h2>
                            <p className="text-white/60 text-lg font-medium mb-10">Vos engagements et votre impact en un coup d'œil.</p>
                            <div className="grid grid-cols-3 gap-4 md:gap-8 max-w-2xl">
                                <div className="bg-white/10 backdrop-blur-md rounded-[1.5rem] p-5 md:p-6 border border-white/10">
                                    <p className="text-[10px] font-black uppercase tracking-widest text-white/50 mb-1">Missions</p>
                                    <p className="text-3xl font-black">{myMissions.length}</p>
                                </div>
                                <div className="bg-white/10 backdrop-blur-md rounded-[1.5rem] p-5 md:p-6 border border-white/10">
                                    <p className="text-[10px] font-black uppercase tracking-widest text-white/50 mb-1">Assos</p>
                                    <p className="text-3xl font-black">{joinedOrgIds.length}</p>
                                </div>
                                <div className="bg-white/10 backdrop-blur-md rounded-[1.5rem] p-5 md:p-6 border border-white/10">
                                    <p className="text-[10px] font-black uppercase tracking-widest text-white/50 mb-1">Impact</p>
                                    <p className="text-3xl font-black">{myMissions.length * 3}h</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    <section>
                      <div className="flex justify-between items-center mb-6">
                        <h3 className="text-2xl font-black tracking-tight">Mes Prochaines Missions</h3>
                        <button onClick={() => setActiveTab('organizations')} className="text-primary-600 font-black text-sm hover:underline flex items-center gap-1">Explorer <ArrowRight className="w-4 h-4"/></button>
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {myMissions.map(m => (
                          <MissionCard key={m.id} mission={m} role="volunteer" currentUser={state.currentUser} allUsers={state.users} onAction={handleMissionAction} onChat={setActiveChatMissionId} onViewParticipants={setViewingParticipantsMissionId} organizationName={state.organizations.find(o => o.id === m.organizationId)?.name} />
                        ))}

                        {/* Explorateur Direct Card */}
                        <button 
                          onClick={() => setActiveTab('organizations')}
                          className="bg-white dark:bg-slate-900 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-[2rem] p-8 flex flex-col items-center justify-center text-center group hover:border-primary-500 hover:bg-primary-50/30 transition-all duration-300 min-h-[300px]"
                        >
                            <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-6 group-hover:bg-primary-100 group-hover:scale-110 transition-all">
                                <Search className="w-8 h-8 text-slate-400 group-hover:text-primary-600" />
                            </div>
                            <h4 className="font-black text-xl mb-2 text-slate-800 dark:text-white">Envie d'aider plus ?</h4>
                            <p className="text-slate-500 text-sm mb-6">Explorez de nouvelles associations et trouvez votre prochaine mission.</p>
                            <span className="flex items-center gap-2 px-6 py-2 bg-slate-100 dark:bg-slate-800 rounded-full text-xs font-black uppercase tracking-widest text-slate-600 dark:text-slate-300 group-hover:bg-primary-600 group-hover:text-white transition-all">Parcourir</span>
                        </button>
                      </div>
                    </section>
                  </>
                )}
              </>
            )}

            {activeTab === 'organizations' && (
              <section className="space-y-10 animate-in fade-in slide-in-from-bottom-6 duration-500">
                <div className="flex justify-between items-end">
                  <div className="flex flex-col gap-2">
                    <h2 className="text-4xl font-black tracking-tighter">Explorer</h2>
                    <p className="text-slate-500 font-medium">Rejoignez des associations pour accéder à leurs missions.</p>
                  </div>
                  {joinedOrgIds.length > 0 && (
                    <Button variant="ghost" className="text-primary-600 font-black" onClick={() => setActiveTab('dashboard')}>
                      Mon Tableau de Bord <ArrowRight className="w-4 h-4 ml-2" />
                    </Button>
                  )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pb-20">
                  {state.organizations.map(org => {
                    const isMember = joinedOrgIds.includes(org.id);
                    return (
                      <div key={org.id} className={`group bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 border-2 transition-all duration-300 ${isMember ? 'border-primary-500 shadow-xl shadow-primary-50' : 'border-slate-100 hover:border-slate-300 shadow-sm'}`}>
                        <div className="flex justify-between items-start mb-8">
                           <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center transition-colors ${isMember ? 'bg-primary-600 text-white shadow-lg' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}`}>
                              <Building className="w-8 h-8" />
                           </div>
                           {isMember && (
                             <div className="flex flex-col items-end gap-2 animate-in zoom-in-95">
                                <span className="flex items-center gap-1.5 px-4 py-2 bg-emerald-100 text-emerald-700 rounded-full text-xs font-black uppercase tracking-widest">
                                    <Check className="w-3.5 h-3.5" /> Membre
                                </span>
                                <button onClick={() => setActiveTab('dashboard')} className="text-[10px] font-black text-primary-600 uppercase tracking-widest hover:underline flex items-center gap-1">Voir mon espace <ArrowRight className="w-2.5 h-2.5"/></button>
                             </div>
                           )}
                        </div>

                        <h3 className="text-2xl font-black text-slate-900 dark:text-white mb-2">{org.name}</h3>
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-10">Code d'accès : {org.code}</p>

                        <div className="flex flex-col gap-3">
                          {isMember ? (
                              <Button variant="danger" fullWidth onClick={() => handleLeaveOrganization(org.id)} className="bg-red-50 text-red-500 hover:bg-red-100 border-none transition-all">
                                <LogOut className="w-4 h-4 mr-2" /> Quitter
                              </Button>
                          ) : (
                            <Button fullWidth size="lg" onClick={() => handleJoinOrganization(org.id)} className="shadow-lg shadow-primary-100">Rejoindre l'équipe</Button>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </section>
            )}
          </div>
        )}
      </main>

      {/* Common Modals */}
      <Modal isOpen={isLogoutModalOpen} onClose={() => setIsLogoutModalOpen(false)} title="Se déconnecter">
          <div className="space-y-6 py-4 text-center">
              <p className="text-slate-500 font-medium">Êtes-vous sûr de vouloir quitter votre espace ?</p>
              <div className="flex flex-col gap-3">
                  <Button variant="danger" size="lg" fullWidth onClick={() => { setState(prev => ({...prev, currentUser: null, currentRole: 'none'})); setIsLogoutModalOpen(false); }}>Confirmer la déconnexion</Button>
                  <Button variant="ghost" fullWidth onClick={() => setIsLogoutModalOpen(false)}>Annuler</Button>
              </div>
          </div>
      </Modal>

      {activeChatMissionId && (
        <ChatDrawer mission={state.missions.find(m => m.id === activeChatMissionId)!} currentUser={state.currentUser!} onClose={() => setActiveChatMissionId(null)} onSendMessage={handleSendMessage} />
      )}

      <Modal isOpen={!!viewingParticipantsMissionId} onClose={() => setViewingParticipantsMissionId(null)} title="Bénévoles Inscrits">
          <div className="space-y-4">
              {state.missions.find(m => m.id === viewingParticipantsMissionId)?.participants.map(pid => {
                  const user = state.users.find(u => u.id === pid);
                  if (!user) return null;
                  return (
                      <div key={user.id} className="flex items-center gap-4 p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl">
                          <img src={user.avatar} className="w-12 h-12 rounded-xl object-cover" />
                          <p className="font-black text-slate-900 dark:text-white">{user.firstName} {user.lastName}</p>
                      </div>
                  );
              })}
              <Button fullWidth onClick={() => setViewingParticipantsMissionId(null)}>Fermer</Button>
          </div>
      </Modal>
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Users, Calendar as CalendarIcon, LogOut, Plus, 
  BarChart3, LayoutDashboard, Heart, Search, Settings, Pencil, X,
  ChevronLeft, ChevronRight, Building, Tag, Eye, Key, Copy, CheckCircle,
  ArrowLeft, ListTodo, Map as MapIcon, Navigation, MapPin, ExternalLink, Flag, Trash2, Target, Check, Globe,
  ArrowRightLeft,
  Sparkles,
  ArrowRight
} from 'lucide-react';
import { BarChart, Bar, XAxis, Tooltip as RechartsTooltip, ResponsiveContainer, Cell } from 'recharts';

import { MissionCard } from './components/MissionCard';
import { ChatDrawer } from './components/ChatDrawer';
import { Button } from './components/ui/Button';
import { Input } from './components/ui/Input';
import { Modal } from './components/ui/Modal';
import { MOCK_MISSIONS, MOCK_USERS, MOCK_ORG, MOCK_ORG_2, MOCK_ORG_3, MOCK_ORG_4, MOCK_ORG_5, MOCK_ORG_6 } from './constants';
import { AppState, Mission, Role, User, Organization, MissionObjective } from './types';

// --- MAIN APP COMPONENT ---

export default function App() {
  const [state, setState] = useState<AppState>({
    currentUser: null,
    currentRole: 'none',
    currentOrganization: null,
    managedOrganization: MOCK_ORG,
    missions: MOCK_MISSIONS,
    users: MOCK_USERS,
    organizations: [MOCK_ORG, MOCK_ORG_2, MOCK_ORG_3, MOCK_ORG_4, MOCK_ORG_5, MOCK_ORG_6]
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'calendar' | 'missions' | 'organizations' | 'volunteers'>('dashboard');
  const [activeChatMissionId, setActiveChatMissionId] = useState<string | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<string>('Tout');

  const [showOrgLogin, setShowOrgLogin] = useState(false);
  const [showVolunteerLogin, setShowVolunteerLogin] = useState(false);

  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [isMissionModalOpen, setIsMissionModalOpen] = useState(false);
  const [isOrgNameModalOpen, setIsOrgNameModalOpen] = useState(false);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

  const [isOrgCodeModalOpen, setIsOrgCodeModalOpen] = useState(false);
  const [isManageOrgsModalOpen, setIsManageOrgsModalOpen] = useState(false);
  const [isCreateVolunteerModalOpen, setIsCreateVolunteerModalOpen] = useState(false);
  const [joinCodeInput, setJoinCodeInput] = useState('');

  const [viewingParticipantsMissionId, setViewingParticipantsMissionId] = useState<string | null>(null);
  const [viewingMapMission, setViewingMapMission] = useState<Mission | null>(null);
  const [isMapPickerOpen, setIsMapPickerOpen] = useState(false);
  const [pickingObjectiveId, setPickingObjectiveId] = useState<string | null>(null);

  const [calendarDate, setCalendarDate] = useState(new Date());

  const [orgLoginData, setOrgLoginData] = useState({ email: '', password: '' });
  const [volunteerLoginData, setVolunteerLoginData] = useState({ username: '', password: '' });
  const [createVolunteerData, setCreateVolunteerData] = useState({ firstName: '', lastName: '', username: '', password: '' });

  const [rememberOrg, setRememberOrg] = useState(false);
  const [profileFormData, setProfileFormData] = useState<Partial<User>>({});

  const [missionFormData, setMissionFormData] = useState<Partial<Mission>>({
    id: undefined,
    title: '', location: '', description: '', category: 'Event', dateStart: '', dateEnd: '',
    objectives: []
  });

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markerRef = useRef<any>(null);

  // Stats calculate for volunteers
  const joinedOrgIds = state.currentUser?.organizationIds || [];
  const volunteerMissions = state.missions.filter(m => joinedOrgIds.includes(m.organizationId));
  const myMissions = volunteerMissions.filter(m => m.participants.includes(state.currentUser?.id || ''));

  useEffect(() => {
    const savedSession = localStorage.getItem('bnevo_org_session');
    if (savedSession) {
      try {
        const session = JSON.parse(savedSession);
        if (session.role === 'organizer') {
          setState(prev => ({
            ...prev,
            currentUser: MOCK_USERS.find(u => u.role === 'organizer') || null,
            currentRole: 'organizer',
            currentOrganization: session.organization || prev.managedOrganization,
            managedOrganization: session.organization || prev.managedOrganization
          }));
        }
      } catch (e) {
        console.error("Failed to parse session", e);
        localStorage.removeItem('bnevo_org_session');
      }
    }
  }, []);

  const toggleRole = () => {
    const newRole: Role = state.currentRole === 'volunteer' ? 'organizer' : 'volunteer';
    setState(prev => ({
      ...prev,
      currentRole: newRole,
      currentOrganization: newRole === 'organizer' ? prev.managedOrganization : (prev.currentUser?.organizationIds?.[0] ? prev.organizations.find(o => o.id === prev.currentUser?.organizationIds![0]) || null : null)
    }));
    setActiveTab('dashboard');
  };

  const createTitleIcon = (L: any, title: string) => {
    return L.divIcon({
      className: 'custom-div-icon',
      html: `<div class="flex items-center gap-2 bg-white dark:bg-slate-900 px-3 py-1.5 rounded-full shadow-lg border-2 border-primary-500 whitespace-nowrap group hover:scale-110 transition-transform">
               <div class="w-2 h-2 rounded-full bg-primary-600"></div>
               <span class="text-xs font-bold text-slate-800 dark:text-slate-100">${title || 'Objectif'}</span>
             </div>`,
      iconSize: [120, 32],
      iconAnchor: [60, 16]
    });
  };

  useEffect(() => {
    if (isMapPickerOpen && mapContainerRef.current && (window as any).L && pickingObjectiveId) {
      const L = (window as any).L;
      const currentObjective = missionFormData.objectives?.find(o => o.id === pickingObjectiveId);
      const initialCoords = currentObjective ? { lat: currentObjective.lat, lng: currentObjective.lng } : { lat: 48.8566, lng: 2.3522 }; 

      if (!mapInstanceRef.current) {
        mapInstanceRef.current = L.map(mapContainerRef.current).setView([initialCoords.lat, initialCoords.lng], 13);
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
          attribution: '© OpenStreetMap'
        }).addTo(mapInstanceRef.current);

        mapInstanceRef.current.on('click', (e: any) => {
          const { lat, lng } = e.latlng;
          setMissionFormData(prev => ({
            ...prev,
            objectives: prev.objectives?.map(o => 
              o.id === pickingObjectiveId ? { ...o, lat, lng } : o
            )
          }));
          if (markerRef.current) {
            markerRef.current.setLatLng(e.latlng);
            markerRef.current.setIcon(createTitleIcon(L, currentObjective?.title || ''));
          } else {
            markerRef.current = L.marker(e.latlng, { icon: createTitleIcon(L, currentObjective?.title || '') }).addTo(mapInstanceRef.current);
          }
        });
      }

      if (currentObjective) {
          if (markerRef.current) {
            markerRef.current.setLatLng([currentObjective.lat, currentObjective.lng]);
            markerRef.current.setIcon(createTitleIcon(L, currentObjective.title));
          } else {
            markerRef.current = L.marker([currentObjective.lat, currentObjective.lng], { icon: createTitleIcon(L, currentObjective.title) }).addTo(mapInstanceRef.current);
          }
      }
    }

    return () => {
      if (!isMapPickerOpen && mapInstanceRef.current) {
        mapInstanceRef.current.remove();
        mapInstanceRef.current = null;
        markerRef.current = null;
      }
    };
  }, [isMapPickerOpen, pickingObjectiveId, missionFormData.objectives]);

  useEffect(() => {
    if (viewingMapMission && mapContainerRef.current && (window as any).L) {
      const L = (window as any).L;
      const objectives = viewingMapMission.objectives || [];

      if (objectives.length === 0) return;

      const viewerMap = L.map(mapContainerRef.current);
      mapInstanceRef.current = viewerMap;
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap'
      }).addTo(viewerMap);

      const markers = objectives.map(obj => {
          return L.marker([obj.lat, obj.lng], { icon: createTitleIcon(L, obj.title) })
            .addTo(viewerMap);
      });

      const group = new L.featureGroup(markers);
      viewerMap.fitBounds(group.getBounds().pad(0.3));

      return () => {
        viewerMap.remove();
        mapInstanceRef.current = null;
      };
    }
  }, [viewingMapMission]);

  const handleObjectiveFocus = (obj: MissionObjective) => {
    if (mapInstanceRef.current) {
      mapInstanceRef.current.setView([obj.lat, obj.lng], 17, { animate: true });
    }
  };

  const detectLocation = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((position) => {
        const { latitude, longitude } = position.coords;
        if (pickingObjectiveId) {
            setMissionFormData(prev => ({
                ...prev,
                objectives: prev.objectives?.map(o => 
                    o.id === pickingObjectiveId ? { ...o, lat: latitude, lng: longitude } : o
                )
            }));
            if (mapInstanceRef.current) {
                mapInstanceRef.current.setView([latitude, longitude], 15);
                const currentObj = missionFormData.objectives?.find(o => o.id === pickingObjectiveId);
                if (markerRef.current) {
                  markerRef.current.setLatLng([latitude, longitude]);
                  markerRef.current.setIcon(createTitleIcon((window as any).L, currentObj?.title || ''));
                } else {
                  markerRef.current = (window as any).L.marker([latitude, longitude], { icon: createTitleIcon((window as any).L, currentObj?.title || '') }).addTo(mapInstanceRef.current);
                }
            }
        }
      });
    } else {
      alert("La géolocalisation n'est pas supportée par votre navigateur.");
    }
  };

  const handleOrgLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (orgLoginData.email && orgLoginData.password) {
      const orgUser = MOCK_USERS.find(u => u.role === 'organizer');
      const orgData = state.managedOrganization;
      setState(prev => ({
        ...prev,
        currentUser: orgUser || null,
        currentRole: 'organizer',
        currentOrganization: orgData
      }));
      setShowOrgLogin(false);
    }
  };

  const handleVolunteerLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const user = state.users.find(u => 
      u.role === 'volunteer' && 
      u.username.toLowerCase() === volunteerLoginData.username.toLowerCase() &&
      u.password === volunteerLoginData.password
    );
    if (user) {
      setState(prev => ({ ...prev, currentUser: user, currentRole: 'volunteer', currentOrganization: prev.organizations.find(o => o.id === user.organizationIds?.[0]) || null }));
      setShowVolunteerLogin(false);
      setActiveTab('dashboard');
    } else {
      alert("Identifiants incorrects.");
    }
  };

  const handleCreateVolunteer = () => {
    if (!createVolunteerData.firstName || !createVolunteerData.username || !createVolunteerData.password) return;
    const newUser: User = {
        id: `u-${Date.now()}`,
        firstName: createVolunteerData.firstName,
        lastName: createVolunteerData.lastName || '',
        username: createVolunteerData.username,
        password: createVolunteerData.password,
        avatar: `https://ui-avatars.com/api/?name=${createVolunteerData.firstName}&background=random`, 
        role: 'volunteer',
        organizationIds: []
    };
    setState(prev => ({ ...prev, users: [...prev.users, newUser], currentUser: newUser, currentRole: 'volunteer' }));
    setIsCreateVolunteerModalOpen(false);
    setShowVolunteerLogin(false);
    setActiveTab('organizations');
  };

  const handleJoinOrganization = (orgId: string) => {
    const orgToJoin = state.organizations.find(o => o.id === orgId);
    if (!orgToJoin) return;

    const updatedUser = {
      ...state.currentUser!,
      organizationIds: Array.from(new Set([...(state.currentUser?.organizationIds || []), orgToJoin.id]))
    };

    setState(prev => ({
      ...prev,
      currentUser: updatedUser,
      users: prev.users.map(u => u.id === updatedUser.id ? updatedUser : u)
    }));
  };

  const handleLeaveOrganization = (orgId: string) => {
    if (!window.confirm("Quitter cette association ?")) return;
    const currentUserId = state.currentUser!.id;
    const updatedUser = {
      ...state.currentUser!,
      organizationIds: state.currentUser!.organizationIds?.filter(id => id !== orgId) || []
    };
    setState(prev => ({
      ...prev,
      users: prev.users.map(u => u.id === currentUserId ? updatedUser : u),
      currentUser: updatedUser
    }));
  };

  const handleMissionAction = (missionId: string) => {
    if (state.currentRole === 'volunteer') {
      setState(prev => {
        const mission = prev.missions.find(m => m.id === missionId);
        if (!mission || !prev.currentUser) return prev;
        const isRegistered = mission.participants.includes(prev.currentUser.id);
        const newParticipants = isRegistered 
            ? mission.participants.filter(id => id !== prev.currentUser!.id)
            : [...mission.participants, prev.currentUser.id];
        return { ...prev, missions: prev.missions.map(m => m.id === missionId ? { ...m, participants: newParticipants } : m) };
      });
    } else {
      const missionToEdit = state.missions.find(m => m.id === missionId);
      if (missionToEdit) {
          setMissionFormData({ ...missionToEdit });
          setIsMissionModalOpen(true);
      }
    }
  };

  const handleSendMessage = (missionId: string, text: string) => {
    const newMessage = {
      id: Date.now().toString(),
      userId: state.currentUser!.id,
      userName: state.currentUser!.firstName,
      userAvatar: state.currentUser!.avatar,
      text,
      timestamp: Date.now()
    };
    setState(prev => ({ ...prev, missions: prev.missions.map(m => m.id === missionId ? { ...m, chatMessages: [...m.chatMessages, newMessage] } : m) }));
  };

  const toLocalISOString = (date: Date) => {
    const pad = (num: number) => num.toString().padStart(2, '0');
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
  };

  const getDaysInMonth = (date: Date) => {
    const year = date.getFullYear();
    const month = date.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const firstDayObj = new Date(year, month, 1);
    let firstDay = firstDayObj.getDay();
    const offset = firstDay === 0 ? 6 : firstDay - 1;
    return { daysInMonth, offset, year, month };
  };

  const changeMonth = (delta: number) => {
    const newDate = new Date(calendarDate);
    newDate.setMonth(newDate.getMonth() + delta);
    setCalendarDate(newDate);
  };

  const Header = () => (
    <header className="sticky top-0 z-40 bg-white/90 dark:bg-slate-900/90 backdrop-blur-lg border-b border-slate-200 dark:border-slate-800 shadow-sm">
      <div className="max-w-5xl mx-auto px-4 h-16 md:h-20 flex items-center justify-between">
        <div className="flex items-center gap-3">
           <div className="w-9 h-9 md:w-10 md:h-10 bg-primary-600 rounded-xl flex items-center justify-center shadow-lg shadow-primary-200">
             <Heart className="w-5 h-5 text-white fill-current" />
           </div>
           <div className="flex flex-col">
             <span className="font-black text-base md:text-xl tracking-tighter text-slate-900 dark:text-white leading-none">BNEVO</span>
             <p className="text-[10px] md:text-xs text-slate-400 font-bold uppercase tracking-widest mt-0.5">Community Hub</p>
           </div>
        </div>

        {/* Navigation Bénévole (Mon Espace / Explorer) */}
        {state.currentRole === 'volunteer' && (
          <div className="bg-slate-100 dark:bg-slate-800 p-1 rounded-xl flex items-center shadow-inner scale-90 md:scale-100">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${activeTab === 'dashboard' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-sm' : 'text-slate-500'}`}
            >
              Mon Espace
            </button>
            <button 
              onClick={() => setActiveTab('organizations')}
              className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${activeTab === 'organizations' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-sm' : 'text-slate-500'}`}
            >
              Explorer
            </button>
          </div>
        )}

        <div className="flex items-center gap-2 md:gap-4">
          {/* Le bouton Role Switch ne s'affiche que si on n'est pas bénévole ou si on veut garder la possibilité d'être orga */}
          {state.currentRole === 'organizer' && (
            <button 
              onClick={toggleRole}
              className="flex items-center gap-2 px-3 py-2 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-xl hover:bg-primary-50 dark:hover:bg-primary-900/20 hover:text-primary-600 transition-all active:scale-95 border border-transparent hover:border-primary-200"
              title="Basculer vers Bénévole"
            >
              <ArrowRightLeft className="w-4 h-4" />
              <span className="text-[10px] md:text-xs font-black uppercase tracking-widest hidden sm:block">Mode Bénévole</span>
            </button>
          )}

          <div className="flex items-center gap-2">
             <div className="text-right hidden sm:block">
               <p className="text-sm font-black text-slate-900 dark:text-white leading-none">{state.currentUser?.firstName}</p>
               <p className="text-[9px] text-slate-400 uppercase tracking-widest font-black mt-1">
                  {state.currentRole === 'organizer' ? 'Organisateur' : 'Bénévole'}
               </p>
             </div>
             <button onClick={() => setIsProfileModalOpen(true)} className="relative active:scale-95 transition-transform">
                <img src={state.currentUser?.avatar} alt="Profile" className="w-9 h-9 md:w-11 md:h-11 rounded-xl object-cover border-2 border-white dark:border-slate-800 shadow-sm" />
             </button>
          </div>
          <button onClick={() => setIsLogoutModalOpen(true)} className="p-2 text-slate-400 hover:text-red-500 transition-colors"><LogOut className="w-5 h-5" /></button>
        </div>
      </div>
    </header>
  );

  if (state.currentRole === 'none') {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50 dark:bg-slate-950">
        <div className="max-w-md w-full text-center space-y-12">
          <div className="mx-auto w-24 h-24 bg-primary-600 rounded-[2.5rem] flex items-center justify-center shadow-2xl shadow-primary-200 animate-bounce-slow">
            <Heart className="w-12 h-12 text-white fill-current" />
          </div>
          <div>
            <h1 className="text-5xl font-black text-slate-900 dark:text-white tracking-tighter">BNEVO</h1>
            <p className="mt-4 text-slate-500 dark:text-slate-400 font-medium">L'engagement solidaire, simplifié à l'extrême.</p>
          </div>

          <div className="space-y-4 pt-6">
            {!showOrgLogin && !showVolunteerLogin ? (
              <>
                <Button fullWidth size="lg" onClick={() => setShowVolunteerLogin(true)}>Espace Bénévole</Button>
                <Button variant="secondary" fullWidth size="lg" onClick={() => setShowOrgLogin(true)}>Accès Organisateur</Button>
              </>
            ) : showOrgLogin ? (
              <div className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] shadow-2xl border border-slate-100 text-left animate-in fade-in slide-in-from-bottom-4">
                <button onClick={() => setShowOrgLogin(false)} className="mb-6 flex items-center gap-2 text-slate-400 hover:text-slate-900 font-bold text-sm"><ArrowLeft className="w-4 h-4"/> Retour</button>
                <h3 className="text-2xl font-black mb-6">Connexion Orga</h3>
                <form onSubmit={handleOrgLoginSubmit} className="space-y-5">
                  <Input label="Email" type="email" value={orgLoginData.email} onChange={e => setOrgLoginData({...orgLoginData, email: e.target.value})} required />
                  <Input label="Mot de passe" type="password" value={orgLoginData.password} onChange={e => setOrgLoginData({...orgLoginData, password: e.target.value})} required />
                  <Button type="submit" fullWidth size="lg">Se connecter</Button>
                </form>
              </div>
            ) : (
              <div className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] shadow-2xl border border-slate-100 text-left animate-in fade-in slide-in-from-bottom-4">
                <button onClick={() => setShowVolunteerLogin(false)} className="mb-6 flex items-center gap-2 text-slate-400 hover:text-slate-900 font-bold text-sm"><ArrowLeft className="w-4 h-4"/> Retour</button>
                <h3 className="text-2xl font-black mb-6">Connexion Bénévole</h3>
                <form onSubmit={handleVolunteerLoginSubmit} className="space-y-5">
                  <Input label="Pseudo" value={volunteerLoginData.username} onChange={e => setVolunteerLoginData({...volunteerLoginData, username: e.target.value})} required />
                  <Input label="Mot de passe" type="password" value={volunteerLoginData.password} onChange={e => setVolunteerLoginData({...volunteerLoginData, password: e.target.value})} required />
                  <Button type="submit" fullWidth size="lg">Entrer</Button>
                  <Button variant="ghost" fullWidth onClick={() => setIsCreateVolunteerModalOpen(true)}>Créer un compte</Button>
                </form>
              </div>
            )}
          </div>
        </div>

        <Modal isOpen={isCreateVolunteerModalOpen} onClose={() => setIsCreateVolunteerModalOpen(false)} title="Nouveau Bénévole">
            <form onSubmit={(e) => { e.preventDefault(); handleCreateVolunteer(); }} className="space-y-4">
                <Input label="Prénom" value={createVolunteerData.firstName} onChange={e => setCreateVolunteerData({...createVolunteerData, firstName: e.target.value})} required />
                <Input label="Identifiant" value={createVolunteerData.username} onChange={e => setCreateVolunteerData({...createVolunteerData, username: e.target.value})} required />
                <Input label="Mot de passe" type="password" value={createVolunteerData.password} onChange={e => setCreateVolunteerData({...createVolunteerData, password: e.target.value})} required />
                <Button type="submit" fullWidth size="lg" className="mt-4">S'inscrire</Button>
            </form>
        </Modal>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white pb-24 md:pb-8">
      <Header />

      {/* Navigation Mobile uniquement pour l'organisateur (car le bénévole a son toggle en haut) */}
      {state.currentRole === 'organizer' && (
        <div className="md:hidden fixed bottom-6 left-1/2 -translate-x-1/2 bg-white/90 dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 p-1.5 flex gap-1 rounded-2xl z-30 shadow-2xl backdrop-blur-md">
           <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-3 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-primary-600 text-white shadow-lg' : 'text-slate-400'}`}>
             <LayoutDashboard className="w-5 h-5" />
             <span className="text-sm font-bold">Dashboard</span>
           </button>
           <button onClick={() => setActiveTab('organizations')} className={`flex items-center gap-2 px-6 py-3 rounded-xl transition-all ${activeTab === 'organizations' ? 'bg-primary-600 text-white shadow-lg' : 'text-slate-400'}`}>
             <Globe className="w-5 h-5" />
             <span className="text-sm font-bold">Assos</span>
           </button>
        </div>
      )}

      <main className="max-w-5xl mx-auto px-4 py-6 md:py-10">
        {state.currentRole === 'organizer' ? (
          <div className="space-y-8 animate-in fade-in duration-500">
             {activeTab === 'dashboard' && (
               <div className="space-y-8">
                  <section className="grid grid-cols-2 md:grid-cols-4 gap-4">
                     {[
                       { label: 'Missions', val: state.missions.filter(m => m.organizationId === state.currentOrganization?.id).length },
                       { label: 'Bénévoles', val: state.users.filter(u => u.organizationIds?.includes(state.currentOrganization?.id || '')).length },
                       { label: 'Participations', val: state.missions.filter(m => m.organizationId === state.currentOrganization?.id).reduce((acc, m) => acc + m.participants.length, 0) }
                     ].map((s, i) => (
                       <div key={i} className="bg-white dark:bg-slate-900 p-6 rounded-[1.5rem] border border-slate-100 shadow-sm">
                          <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1">{s.label}</p>
                          <p className="text-3xl font-black">{s.val}</p>
                       </div>
                     ))}
                     <button onClick={() => setIsMissionModalOpen(true)} className="bg-primary-600 text-white p-6 rounded-[1.5rem] shadow-lg flex flex-col justify-center items-center hover:bg-primary-700 transition-all active:scale-95">
                        <Plus className="w-8 h-8 mb-1" />
                        <p className="font-black text-[10px] uppercase tracking-widest">Nouveau</p>
                     </button>
                  </section>
                  <section className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {state.missions.filter(m => m.organizationId === state.currentOrganization?.id).map(m => (
                      <MissionCard key={m.id} mission={m} role="organizer" currentUser={state.currentUser} allUsers={state.users} onAction={handleMissionAction} onChat={setActiveChatMissionId} onViewParticipants={setViewingParticipantsMissionId} onViewMap={setViewingMapMission} />
                    ))}
                  </section>
               </div>
             )}
          </div>
        ) : (
          <div className="space-y-10 animate-in fade-in duration-500">
            {activeTab === 'dashboard' && (
              <>
                {joinedOrgIds.length === 0 ? (
                   <div className="bg-white dark:bg-slate-900 rounded-[3rem] p-12 text-center border-2 border-slate-100 dark:border-slate-800 shadow-xl">
                      <div className="w-24 h-24 bg-primary-100 dark:bg-primary-900/30 rounded-[2rem] flex items-center justify-center mx-auto mb-8"><Sparkles className="w-12 h-12 text-primary-600" /></div>
                      <h2 className="text-3xl font-black mb-4">Prêt à faire la différence ?</h2>
                      <p className="text-slate-500 dark:text-slate-400 mb-10 max-w-sm mx-auto text-lg">Rejoins ta première association pour débloquer ton espace personnel.</p>
                      <Button onClick={() => setActiveTab('organizations')} size="lg" className="px-10">Découvrir les associations</Button>
                   </div>
                ) : (
                  <>
                    <div className="bg-gradient-to-br from-slate-900 to-slate-800 dark:from-primary-700 dark:to-primary-900 rounded-[2.5rem] p-8 md:p-12 text-white shadow-2xl relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -translate-y-1/2 translate-x-1/2 blur-3xl" />
                        <div className="relative z-10">
                            <h2 className="text-4xl md:text-5xl font-black mb-2 tracking-tighter">Bienvenue, {state.currentUser?.firstName}</h2>
                            <p className="text-white/60 text-lg font-medium mb-10">Voici l'impact que tu crées aujourd'hui.</p>
                            <div className="grid grid-cols-3 gap-4 md:gap-8 max-w-2xl">
                                <div className="bg-white/10 backdrop-blur-md rounded-[1.5rem] p-5 md:p-6 border border-white/10">
                                    <p className="text-[10px] font-black uppercase tracking-widest text-white/50 mb-1">Missions</p>
                                    <p className="text-3xl font-black">{myMissions.length}</p>
                                </div>
                                <div className="bg-white/10 backdrop-blur-md rounded-[1.5rem] p-5 md:p-6 border border-white/10">
                                    <p className="text-[10px] font-black uppercase tracking-widest text-white/50 mb-1">Assos</p>
                                    <p className="text-3xl font-black">{joinedOrgIds.length}</p>
                                </div>
                                <div className="bg-white/10 backdrop-blur-md rounded-[1.5rem] p-5 md:p-6 border border-white/10">
                                    <p className="text-[10px] font-black uppercase tracking-widest text-white/50 mb-1">Impact</p>
                                    <p className="text-3xl font-black">{myMissions.length * 3}h</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    <section>
                      <div className="flex justify-between items-center mb-6">
                        <h3 className="text-2xl font-black tracking-tight">Mes Prochaines Missions</h3>
                        <button 
                          onClick={() => setActiveTab('organizations')}
                          className="flex items-center gap-1.5 text-primary-600 font-bold text-sm hover:underline"
                        >
                          Explorer plus <ArrowRight className="w-4 h-4" />
                        </button>
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {myMissions.map(m => (
                          <MissionCard key={m.id} mission={m} role="volunteer" currentUser={state.currentUser} allUsers={state.users} onAction={handleMissionAction} onChat={setActiveChatMissionId} onViewParticipants={setViewingParticipantsMissionId} onViewMap={setViewingMapMission} organizationName={state.organizations.find(o => o.id === m.organizationId)?.name} />
                        ))}
                        {myMissions.length === 0 && (
                            <div className="col-span-full py-16 px-8 bg-white dark:bg-slate-900 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-[2.5rem] text-center text-slate-400">
                                <p className="font-black text-xl mb-2 text-slate-300">Aucune mission prévue</p>
                                <p className="text-sm mb-8">Inscris-toi à une mission pour la voir apparaître ici.</p>
                                <Button variant="secondary" onClick={() => setActiveTab('organizations')}>Trouver une mission</Button>
                            </div>
                        )}
                      </div>
                    </section>
                  </>
                )}
              </>
            )}

            {activeTab === 'organizations' && (
              <section className="space-y-10 animate-in fade-in slide-in-from-bottom-6">
                <div className="flex justify-between items-end">
                  <div className="flex flex-col gap-2">
                    <h2 className="text-4xl font-black tracking-tighter">Associations</h2>
                    <p className="text-slate-500 font-medium">Parcourez les opportunités d'aider autour de vous.</p>
                  </div>
                  {joinedOrgIds.length > 0 && (
                    <Button variant="ghost" className="text-primary-600 font-black mb-2" onClick={() => setActiveTab('dashboard')}>
                      Voir mon espace <ArrowRight className="w-4 h-4 ml-2" />
                    </Button>
                  )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {state.organizations.map(org => {
                    const isMember = joinedOrgIds.includes(org.id);
                    return (
                      <div key={org.id} className={`group bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 border-2 transition-all duration-300 ${isMember ? 'border-primary-500 shadow-xl shadow-primary-50' : 'border-slate-100 hover:border-slate-300 shadow-sm'}`}>
                        <div className="flex justify-between items-start mb-8">
                           <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center transition-colors ${isMember ? 'bg-primary-600 text-white' : 'bg-slate-100 text-slate-400'}`}>
                              <Building className="w-8 h-8" />
                           </div>
                           {isMember && (
                             <div className="animate-in zoom-in-50 duration-300 flex flex-col items-end gap-2">
                                <span className="flex items-center gap-1.5 px-4 py-2 bg-emerald-100 text-emerald-700 rounded-full text-xs font-black uppercase tracking-widest">
                                    <Check className="w-3.5 h-3.5" /> Membre
                                </span>
                             </div>
                           )}
                        </div>

                        <h3 className="text-2xl font-black text-slate-900 dark:text-white mb-2">{org.name}</h3>
                        <p className="text-xs text-slate-400 font-black uppercase tracking-widest mb-10">Code d'accès : {org.code}</p>

                        <div className="flex flex-col gap-3">
                          {isMember ? (
                              <Button variant="danger" fullWidth onClick={() => handleLeaveOrganization(org.id)} className="bg-red-50 text-red-500 hover:bg-red-100 border-none">
                                <LogOut className="w-4 h-4 mr-2" /> Quitter
                              </Button>
                          ) : (
                            <Button fullWidth size="lg" onClick={() => handleJoinOrganization(org.id)}>Rejoindre l'équipe</Button>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </section>
            )}
          </div>
        )}
      </main>

      {/* Common Modals */}
      <Modal isOpen={isLogoutModalOpen} onClose={() => setIsLogoutModalOpen(false)} title="Se déconnecter">
          <div className="space-y-6 py-4 text-center">
              <p className="text-slate-500 font-medium">Êtes-vous sûr de vouloir quitter votre espace ?</p>
              <div className="flex flex-col gap-3">
                  <Button variant="danger" size="lg" fullWidth onClick={() => { setState(prev => ({...prev, currentUser: null, currentRole: 'none'})); setIsLogoutModalOpen(false); }}>Confirmer la déconnexion</Button>
                  <Button variant="ghost" fullWidth onClick={() => setIsLogoutModalOpen(false)}>Annuler</Button>
              </div>
          </div>
      </Modal>

      {activeChatMissionId && (
        <ChatDrawer mission={state.missions.find(m => m.id === activeChatMissionId)!} currentUser={state.currentUser!} onClose={() => setActiveChatMissionId(null)} onSendMessage={handleSendMessage} />
      )}

      {/* Participants & Map Modals reuse existing logic */}
      <Modal isOpen={!!viewingParticipantsMissionId} onClose={() => setViewingParticipantsMissionId(null)} title="Bénévoles Inscrits">
          <div className="space-y-4">
              {state.missions.find(m => m.id === viewingParticipantsMissionId)?.participants.map(pid => {
                  const user = state.users.find(u => u.id === pid);
                  if (!user) return null;
                  return (
                      <div key={user.id} className="flex items-center gap-4 p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl">
                          <img src={user.avatar} className="w-12 h-12 rounded-xl object-cover" />
                          <p className="font-black text-slate-900 dark:text-white">{user.firstName} {user.lastName}</p>
                      </div>
                  );
              })}
              <Button fullWidth onClick={() => setViewingParticipantsMissionId(null)}>Fermer</Button>
          </div>
      </Modal>

      <Modal isOpen={!!viewingMapMission} onClose={() => setViewingMapMission(null)} title="Carte de mission">
          <div className="space-y-4">
              <div ref={mapContainerRef} className="h-80 w-full rounded-[2rem] border-2 border-slate-100" />
              <Button fullWidth onClick={() => setViewingMapMission(null)}>Fermer</Button>
          </div>
      </Modal>
    </div>
  );
}
